import subprocess,os
D="/tmp/filetest3"
exts=["txt","dat","log","csv","out","tex","eps","pdb","gro","mdp","top","itp","ndx","edr","trr","xtc","cpt","tng","h5md","xpm","m2p","mtx","edi","inp","rtp","pqr","g96","brk","ent","esp","tpr","xyz","foo","gz","zip","bz2","Z","h5","cub","cube","pqr","res","golden","grd","ene"]
def cls(fn):
    p=subprocess.run(["/workspace/executable","-quiet","bar","-f",fn],capture_output=True,text=True,cwd=D)
    e=p.stderr
    if "cannot be used for this option" in e:return "known-not-allowed"
    if "recognizable extension" in e:return "unknown-exists"
    if "extensions were tried" in e:return "unknown-missing-or-completion"
    if "file could not be opened" in e:return "allowed-missing"
    return e[-150:].replace("\n","|")
for ex in exts:
    fn=f"probe.{ex}"; open(os.path.join(D,fn),"w").write("x")
    print(ex, cls(fn), "missing:", cls("missing."+ex))
PY"}

