randvals={}
for s in seeds:
    libc.srand(s)
    randvals[s]=[libc.rand() for _ in range(5)]
# test candidate N and formula index for k-th rand
def violations(N,k,mode):
    groups={}
    bad=0; seen=0
    for t,q in rows:
        r=randvals[t][k]
        idx=r%N if mode=='mod' else int(r/2147483648*N)
        if idx in groups:
            seen+=1
            if groups[idx]!=q: bad+=1
        else: groups[idx]=q
    return bad,seen,len(groups)
best=[]
for N in range(800,1201):
    for k in range(3):
        for mode in ['mod','scale']:
            bad,seen,groups=violations(N,k,mode)
            if seen and bad/seen<0.2:
                best.append((bad/seen,bad,seen,N,k,mode,groups))
best.sort()
print(best[:20])
PY"}

