def arity(spec):
    kind = spec["kind"]
    if kind == "bool":
        return 0, 1, None
    if spec.get("optional_value"):
        return 0, 1, None
    if kind == "vector":
        return 1, 3, {1, 3}
    if kind == "selection":
        return 1, None, None
    if kind == "string" and spec.get("default") and " " in spec["default"]:
        return 1, None, None
    if kind == "file":
        ph = spec.get("placeholder") or ""
        if ph.startswith("["):
            return 0, (None if spec.get("multi") else 1), None
