def wrap_line(text, indent=""):
    """Greedy word wrapping to 78 columns, as used by GROMACS diagnostics."""
    words = text.split(" ")
    lines = []
    cur = None
    for word in words:
        if cur is None:
            cur = word
        elif len(indent) + len(cur) + 1 + len(word) <= WRAP_WIDTH:
            cur += " " + word
        else:
            lines.append(indent + cur)
            cur = word
    if cur is not None:
        lines.append(indent + cur)
    return "\n".join(lines)


