        self.common_set = set()
        self._banner_written = False
        self._debug_announced = False
        self._quote = None

    # ----- identification / banner -------------------------------------
    def executable_path(self):
        a0 = self.argv0
        if not a0:
            return ""
        if "/" in a0:
            if os.path.islink(a0):
                try:
                    return os.path.realpath(a0)
                except OSError:
                    pass
            if os.path.isabs(a0):
                return a0
            if self.cwd.endswith("/"):
                return self.cwd + a0
            return self.cwd + "/" + a0
        for entry in os.environ.get("PATH", "").split(":"):
            cand = (entry or ".") + "/" + a0
            if os.path.isfile(cand) and os.access(cand, os.X_OK):
                if os.path.islink(cand):
                    return os.path.realpath(cand)
                return a0
