        return err.exit_code


# ---------------------------------------------------------------------------
# C-compatible scalar parsing
# ---------------------------------------------------------------------------

_C_SPACE = r"[ \t\n\v\f\r]*"
_C_DEC = r"(?:(?:\d+\.\d*|\.\d+|\d+)(?:[eE][+-]?\d+)?)"
_C_HEX = r"(?:0[xX](?:[0-9a-fA-F]+\.[0-9a-fA-F]*|\.[0-9a-fA-F]+|[0-9a-fA-F]+)(?:[pP][+-]?\d+)?)"
_C_SPECIAL = r"(?:inf(?:inity)?|nan(?:\([A-Za-z0-9_]*\))?)"
_C_DOUBLE_RE = re.compile(
    r"^" + _C_SPACE + r"[+-]?(?:" + _C_DEC + r"|" + _C_HEX + r"|" + _C_SPECIAL + r")$",
    re.IGNORECASE,
)
_C_INT_RE = re.compile(r"^[ \t\n\v\f\r]*[+-]?\d+$")


def parse_c_double_syntax(token):
    if not _C_DOUBLE_RE.match(token):
        return None
    t = token.strip(" \t\n\v\f\r")
    low = t.lower().lstrip("+-")
    try:
        if low.startswith("nan"):
            val = math.nan
            if t.startswith("-"):
                val = math.copysign(val, -1.0)
            return val
        if low.startswith("inf"):
            return -math.inf if t.startswith("-") else math.inf
        if low.startswith("0x"):
            return float.fromhex(t)
        return float(t)
    except (ValueError, OverflowError):
        # float() produces inf on overflow in CPython rather than raising,
        # but keep the guard for fromhex and unusual inputs.
        return -math.inf if t.startswith("-") else math.inf


def double_range_error(token, value):
    if value is None:
        return False
    t = token.strip(" \t\n\v\f\r").lower().lstrip("+-")
    if t.startswith("inf") or t.startswith("nan"):
        return False
    if math.isinf(value):
        return True
    if value != 0.0 and abs(value) < DBL_MIN:
        return True
    if value == 0.0:
        # Non-zero mantissa that underflowed all the way to zero.
        mantissa = re.split(r"[ep]", t, maxsplit=1)[0]
        if any(ch in "123456789abcdef" for ch in mantissa):
            return True
    return False


def convert_real(token):
    val = parse_c_double_syntax(token)
    if val is None:
        return None, f"Invalid value: '{token}'; expected a number"
    if double_range_error(token, val) or (math.isfinite(val) and abs(val) > FLT_MAX) or math.isinf(val):
        # Literal infinities are rejected for <real> but accepted for <time>.
        if math.isinf(val) and not double_range_error(token, val):
            pass
        return None, f"Invalid value: '{token}'; it causes an overflow/underflow"
    try:
        val = struct.unpack("f", struct.pack("f", val))[0]
    except (OverflowError, struct.error):
        return None, f"Invalid value: '{token}'; it causes an overflow/underflow"
    return val, None


def convert_time(token):
    val = parse_c_double_syntax(token)
    if val is None:
        return None, f"Invalid value: '{token}'; expected a number"
    if double_range_error(token, val):
        return None, f"Invalid value: '{token}'; it causes an overflow/underflow"
    return val, None


def convert_int(token, bits=32):
    if not _C_INT_RE.match(token):
        return None, f"Invalid value: '{token}'; expected an integer"
    try:
        val = int(token.strip(" \t\n\v\f\r"), 10)
    except ValueError:
        return None, f"Invalid value: '{token}'; expected an integer"
    lo = -(1 << (bits - 1))
    hi = (1 << (bits - 1)) - 1
    if val < lo or val > hi:
        return None, f"Invalid value: '{token}'; it causes an integer overflow"
    return val, None


_BOOL_VALUES = {
    "1": True, "0": False, "yes": True, "no": False,
    "true": True, "false": False,
}


def convert_bool(token):
    key = token.lower()
    if key not in _BOOL_VALUES:
        return None, (
            f"Invalid value: '{token}'; supported values are: "
            "1, 0, yes, no, true, false"
        )
    return _BOOL_VALUES[key], None


def convert_enum(token, allowed):
    if token in allowed:
        return token, None
    candidates = [a for a in allowed if a.startswith(token)]
    if not candidates:
        return None, (
            f"Invalid value: {token}. Allowed values: {', '.join(allowed)}."
        )
    # An abbreviated value resolves to the shortest matching name (this
    # matches, for example, -xvg x resolving to xmgr rather than xmgrace).
    candidates.sort(key=lambda a: (len(a), allowed.index(a)))
    return candidates[0], None


# ---------------------------------------------------------------------------
# Option specifications and the command-line parser
# ---------------------------------------------------------------------------

def common_specs():
    def spec(name, kind, default):
        return {
            "name": name, "kind": kind, "placeholder": None,
            "default": default, "marker": None, "section": "common",
            "desc": "", "enum": None, "exts": None, "multi": False,
            "bool": kind == "bool",
        }

    return [
        spec("h", "bool", "no"), spec("quiet", "bool", "no"),
        spec("version", "bool", "no"), spec("copyright", "bool", "no"),
        spec("nice", "int", "19"), spec("backup", "bool", "yes"),
        dict(spec("debug", "int", "0"), optional_value=True),
    ]


def command_specs(cmd):
    specs = []
    for raw in COMMANDS[cmd]["options"]:
        s = dict(raw)
        specs.append(s)
    return specs


def spec_lookup(specs, raw_name):
    """Return (spec, no_prefix) or (None, False)."""
    for s in specs:
        if s["name"] == raw_name:
            return s, False
    if raw_name.startswith("no") and len(raw_name) > 2:
        rest = raw_name[2:]
        for s in specs:
            if s["name"] == rest and s["kind"] == "bool":
                return s, True
    return None, False


def is_option_token(token):
    if not token.startswith("-"):
        return False
    if token in ("-", "--"):
        return False
    if parse_c_double_syntax(token) is not None:
        return False
    return True


def option_raw_name(token):
    if token.startswith("--"):
        return token[2:]
    return token[1:]


class Segment:
    __slots__ = ("token", "values")

    def __init__(self, token):
        self.token = token
        self.values = []


def segment_args(args):
    positionals = []
    segments = []
    cur = None
    for tok in args:
        if is_option_token(tok):
            cur = Segment(tok)
            segments.append(cur)
        elif cur is None:
            positionals.append(tok)
        else:
            cur.values.append(tok)
    return positionals, segments


class OptState:
    def __init__(self, specs):
        self.specs = {s["name"]: s for s in specs}
        self.set_by_user = {}
        self.values = {}
        self.raw_values = {}
        for s in specs:
            self.values[s["name"]] = default_value(s)

    def is_set(self, name):
        return name in self.set_by_user

    def value(self, name, default=None):
        return self.values.get(name, default)

    def file_value(self, name):
        v = self.values.get(name)
        if isinstance(v, list):
            return v[0] if v else None
        return v

    def file_values(self, name):
        v = self.values.get(name)
        if v is None:
            return []
        return list(v) if isinstance(v, list) else [v]


def default_value(spec):
    d = spec.get("default")
    kind = spec["kind"]
    if d is None:
        return None
    try:
        if kind == "bool":
            return d == "yes"
        if kind == "int":
            return int(d)
        if kind in ("real", "time"):
            v = float(d)
            return struct.unpack("f", struct.pack("f", v))[0] if kind == "real" else v
        if kind == "vector":
            return [float(x) for x in d.split()]
        if kind == "string" and " " in d:
            return d.split()
        return d
    except Exception:
        return d


def arity(spec):
    kind = spec["kind"]
    if kind == "bool":
        return 0, 1, None
    if spec.get("optional_value"):
        return 0, 1, None
    if kind == "vector":
        return 1, 3, {1, 3}
    if kind == "selection":
        return 1, None, None
    if kind == "string" and spec.get("default") and " " in spec["default"]:
        return 1, None, None
    if kind == "file":
        ph = spec.get("placeholder") or ""
        if ph.startswith("["):
            return 0, (None if spec.get("multi") else 1), None
        return 1, 1, None
    if kind == "dir":
        return 0, None, None
    return 1, 1, None


def format_option_error(token, details):
    """details: list of (indent, text)."""
    lines = [f"  In command-line option {token}"]
    for indent, text in details:
        pad = " " * indent
        lines.append(wrap_line(text, pad))
    return "\n".join(lines)


# ----- input file name validation ------------------------------------------

def split_file_extension(filename):
    base = filename.rsplit("/", 1)[-1]
    stripped = filename
    if base.lower().endswith(".gz") and len(base) > 3:
        stripped = filename[:-3]
        base = base[:-3]
    if "." not in base:
        return stripped, None
    ext = base.rsplit(".", 1)[-1].lower()
    return stripped, (ext or None)


def _errno_text(error):
    return error.strerror or str(error)


def access_file_details(display, actual):
    try:
        st = os.stat(actual)
    except OSError as e:
        return [
            (4, f"File '{display}' does not exist or is not accessible."),
            (4, "The file could not be opened."),
            (6, f"Reason: {_errno_text(e)}"),
            (6, f"(call to fopen() returned error code {e.errno})"),
        ]
    import stat as _stat

    if not _stat.S_ISREG(st.st_mode):
        return [
            (4, f"Failed to access file '{display}'."),
            (4, "The file is not a regular file."),
        ]
    try:
        fd = os.open(actual, os.O_RDONLY)
        os.close(fd)
    except OSError as e:
        return [
            (4, f"Failed to access file '{display}'."),
            (4, "The file could not be opened."),
            (6, f"Reason: {_errno_text(e)}"),
            (6, f"(call to fopen() returned error code {e.errno})"),
        ]
    return None


def validate_input_filename(value, spec):
    """Return (resolved_name, error_details_or_None)."""
    allowed = list(spec.get("exts") or [])
    stripped, ext = split_file_extension(value)
    is_lib = spec.get("marker") and "Lib." in spec["marker"]

    if ext is not None and ext in KNOWN_FILE_EXTENSIONS:
        if allowed and ext not in allowed:
            return None, [
                (4, f"File name '{value}' cannot be used for this option."),
                (4, "Only the following extensions are possible:"),
                (6, ", ".join("." + e for e in allowed)),
            ]
        if is_lib:
            return value, None
        details = access_file_details(value, value)
        if details:
            return None, details
        return stripped, None

    if is_lib:
        return value, None

    if os.path.lexists(value):
        return None, [
            (4, f"File '{value}' cannot be used by GROMACS because it does not "
                "have a recognizable extension."),
            (4, "The following extensions are possible for this option:"),
            (6, ", ".join("." + e for e in allowed)),
        ]
    for e in allowed:
        cand = f"{value}.{e}"
        if os.path.lexists(cand):
            details = access_file_details(cand, cand)
            if details:
                return None, details
            return cand, None
    return None, [
        (4, f"File '{value}' does not exist or is not accessible."),
        (4, "The following extensions were tried to complete the file name:"),
        (6, ", ".join("." + e for e in allowed)),
    ]


def complete_default_file(spec):
    default = spec.get("default")
    if not default:
        return None, None
    base = default.rsplit("/", 1)[-1]
    stem = default[: len(default) - len(base)] + (base.rsplit(".", 1)[0] if "." in base else base)
    for e in spec.get("exts") or []:
        cand = f"{stem}.{e}"
        if os.path.lexists(cand):
            return cand, stem
    return None, stem


# ----- selection validation (syntax only; expanded by the tools) ----------

from .selections import validate_selection  # noqa: E402


def process_selection_file(ctx, value):
    """Return (selections, details) for a -sf file."""
    try:
        with open(value, "r", encoding="utf-8", errors="surrogateescape") as fh:
            content = fh.read()
    except OSError as e:
        return None, [
            (4, f"Error in parsing selections from file '{value}'"),
            (6, f"Could not open file '{value}'"),
            (8, f"Reason: {_errno_text(e)}"),
            (8, f"(call to fopen() returned error code {e.errno})"),
        ]
    parts = [p.strip() for p in re.split(r"[;\n]", content) if p.strip()]
    if not parts:
        return None, [
            (4, f"Error in adding selections from file '{value}'"),
            (6, "Too few selections provided"),
        ]
    return parts, None


# ----- the parser proper -----------------------------------------------------

def parse_segments(ctx, segments, specs, state, *, only_common=False,
                   common_spec_list=None):
    """Parse option segments into state.

    Returns a list of formatted error entries (strings).  When
    ``only_common`` is true, segments that are not common options are
    silently skipped - this is the first parsing phase for a module.
    """
    errors = []
    seen = {}
    for seg in segments:
        raw = option_raw_name(seg.token)
        if only_common:
            spec, no_prefix = spec_lookup(common_spec_list, raw)
            if spec is None:
                continue
        else:
            spec, no_prefix = spec_lookup(specs, raw)
            if spec is None:
                errors.append(f"    Unknown command-line option {seg.token}")
                continue
        name = spec["name"]
        if name in seen:
            errors.append(format_option_error(
                seg.token, [(4, "Option specified multiple times")]))
            continue
        seen[name] = seg

        occ_errors = []
        converted = []
        values = list(seg.values)

        if spec["kind"] == "selectionfile":
            if not values:
                occ_errors.append((4, "Too few (valid) values"))
            else:
                sels, details = process_selection_file(ctx, values[0])
                if details:
                    occ_errors.extend(details)
                else:
                    converted = [sels]
                if len(values) > 1:
                    occ_errors.append((4, "More than one file name provided"))
            for d in _group_details(occ_errors):
                errors.append(format_option_error(seg.token, [d]))
            if not occ_errors:
                state.set_by_user[name] = True
                state.raw_values[name] = values
                state.values[name] = converted[0] if converted else None
            else:
                state.set_by_user.setdefault(name, True)
                state.raw_values[name] = values
            continue

        for v in values:
            val, detail = convert_value(ctx, spec, v)
            if detail is not None:
                if isinstance(detail, list):
                    occ_errors.extend(detail)
                else:
                    occ_errors.append((4, detail))
                converted.append(None)
            else:
                converted.append(val)

        if no_prefix and values:
            if not any("Cannot specify a value" in t for _, t in occ_errors):
                occ_errors.append(
                    (4, "Cannot specify a value together with 'no' prefix"))

        count_ok = True
        if not occ_errors:
            lo, hi, allowed_counts = arity(spec)
            n = len(values)
            if allowed_counts is not None:
                if n < lo:
                    occ_errors.append((4, "Too few (valid) values")); count_ok = False
                elif hi is not None and n > hi:
                    occ_errors.append((4, "Too many values")); count_ok = False
                elif n not in allowed_counts:
                    occ_errors.append(
                        (4, f"Expected 1 or 3 values, got {n}")); count_ok = False
            else:
                if n < lo:
                    occ_errors.append((4, "Too few (valid) values")); count_ok = False
                elif hi is not None and n > hi:
                    occ_errors.append((4, "Too many values")); count_ok = False

        # Each error detail gets its own "In command-line option" entry,
        # exactly as the reference parser reports them.  Multi-line details
        # (file errors, selection errors) stay together under one entry:
        # convert_value marks the start of such a group by indent 4 and
        # continuation lines carry deeper indents, except file errors whose
        # second line is also indent 4.  Groups were recorded with a
        # sentinel by convert_value - simpler: regroup here conservatively
        # by keeping consecutive details that came from one conversion.
        for group in _regroup(occ_errors):
            errors.append(format_option_error(seg.token, group))

        # Assignment.
        state.raw_values[name] = values
        if spec["kind"] == "bool" and no_prefix and len(values) == 1 \
                and converted and converted[0] is not None:
            state.set_by_user[name] = True
            state.values[name] = converted[0]
        elif not occ_errors:
            state.set_by_user[name] = True
            state.values[name] = assign_value(spec, converted, values, no_prefix)
        else:
            # Remember that the user mentioned the option (matters for
            # common-option handling), but keep the previous/default value.
            state.set_by_user[name] = True
    return errors


def _group_details(details):
    return details


def _regroup(details):
    """Group consecutive detail tuples that belong to one message.

    convert_value separates independent messages using a 0-indent sentinel.
    """
    groups = []
    cur = []
    for indent, text in details:
        if indent == 0:
            if cur:
                groups.append(cur)
            cur = []
            continue
        cur.append((indent, text))
    if cur:
        groups.append(cur)
    return groups


def convert_value(ctx, spec, v):
    kind = spec["kind"]
    if kind == "bool":
        return convert_bool(v)
    if kind == "int":
        bits = 64 if spec["name"] in INT64_OPTIONS else 32
        return convert_int(v, bits)
    if kind == "real" or kind == "vector":
        return convert_real(v)
    if kind == "time":
        return convert_time(v)
    if kind == "enum":
        return convert_enum(v, spec.get("enum") or [])
    if kind in ("string", "dir"):
        return v, None
    if kind == "selection":
        details = validate_selection(v)
        if details:
            return None, details + [(0, "")]
        return v, None
    if kind == "file":
        if spec.get("section") in ("input", "inout"):
            resolved, details = validate_input_filename(v, spec)
            if details:
                return None, details + [(0, "")]
            return resolved, None
        return v, None
    return v, None


def assign_value(spec, converted, raw, no_prefix):
    kind = spec["kind"]
    if kind == "bool":
        if not raw:
            return not no_prefix
        return converted[0]
    if spec.get("optional_value"):
        return converted[0] if raw else 1
    lo, hi, _ = arity(spec)
    if hi is None or kind in ("selection",) or spec.get("multi") or kind == "vector":
        return list(converted)
    if kind == "file" and (spec.get("placeholder") or "").startswith("["):
        return list(converted) if converted else []
    if kind == "string" and spec.get("default") and " " in spec["default"]:
        return list(converted)
    return converted[0] if converted else None


def invalid_options_error(ctx, entries, *, module_stage=True,
                          source="src/gromacs/commandline/cmdlineparser.cpp",
                          line=271):
    body = "Invalid command-line options\n" + "\n".join(entries) + "\n"
    return GmxError(
        body, title="Error in user input:", source=source, line=line,
        function="void gmx::CommandLineParser::parse(int*, char**)",
        module_stage=module_stage,
    )


def positional_error(ctx, token, *, module_stage=True):
    msg = (f"Positional argument '{token}' cannot be accepted. Perhaps you "
           "forgot to put a hyphen before an option name.")
    return GmxError(
        wrap_line(msg) + "\n", title="Error in user input:",
        source="src/gromacs/commandline/cmdlineparser.cpp", line=167,
        function="void gmx::CommandLineParser::parse(int*, char**)",
        module_stage=module_stage,
    )


# ---------------------------------------------------------------------------
# Finishing: default file handling
# ---------------------------------------------------------------------------

def finish_options(ctx, cmd, specs, state):
    errors = []
    for spec in sorted(specs, key=lambda s: s["name"]):
        if spec["kind"] != "file":
            continue
        name = spec["name"]
        section = spec.get("section")
        is_lib = spec.get("marker") and "Lib." in spec["marker"]
        optional = spec.get("marker") and "Opt." in spec["marker"]
        raw = state.raw_values.get(name)
        is_set = state.is_set(name)

        if section == "output":
            if not is_set:
                state.values[name] = None if optional else spec.get("default")
            elif not raw:
                state.values[name] = spec.get("default")
            else:
                state.values[name] = list(raw) if spec.get("multi") else raw[0]
            continue

        # input / inout
        if is_lib:
            if not is_set or not raw:
                state.values[name] = spec.get("default")
            else:
                state.values[name] = list(raw) if spec.get("multi") else raw[0]
            continue
        if is_set and raw:
            # Explicit names were already resolved during parsing; the
            # parsed value holds the resolved name(s).
            continue
        if spec.get("default") is None:
            state.values[name] = None
            continue
        completed, stem = complete_default_file(spec)
        if completed is not None:
            state.values[name] = [completed] if spec.get("multi") else completed
            continue
        if is_set and not raw:
            errors.append((name, [
                (4, f"No file name was provided, and the default file '{stem}' "
                    "does not exist or is not accessible."),
                (4, "The following extensions were tried to complete the file name:"),
                (6, ", ".join("." + e for e in spec.get("exts") or [])),
            ]))
        elif not is_set and not optional:
            errors.append((name, [
                (4, f"Required option was not provided, and the default file "
                    f"'{stem}' does not exist or is not accessible."),
                (4, "The following extensions were tried to complete the file name:"),
                (6, ", ".join("." + e for e in spec.get("exts") or [])),
            ]))
        else:
            state.values[name] = None

    if errors:
        lines = []
        for name, details in errors:
            lines.append(f"  In option {name}")
            for indent, text in details:
                lines.append(wrap_line(text, " " * indent))
        body = "Invalid input values\n" + "\n".join(lines) + "\n"
        raise GmxError(
            body, title="Error in user input:",
            source="src/gromacs/options/options.cpp", line=184,
            function="void gmx::internal::OptionSectionImpl::finish()",
            module_stage=True,
        )


# ---------------------------------------------------------------------------
# Version / help output
# ---------------------------------------------------------------------------

def print_version(ctx):
    out_write(ctx.banner_text(for_version=True))
    out_write("\n")
    out_write(VERSION_BODY)
    return 0


def print_root_help(ctx):
    ctx.ensure_banner()
    out_write(DATA["roothelp"])
    return ctx.finish_success(0)


def run_help_module(ctx, topics):
    """topics: positional arguments to gmx help."""
    if not topics:
        return print_root_help(ctx)
    first = topics[0]
    if first == "commands":
        if len(topics) > 1:
            return help_error(ctx, "Help topic 'commands' has no subtopics")
        ctx.ensure_banner()
        out_write(DATA["commands_topic"])
        return ctx.finish_success(0)
    if first == "selections":
        if len(topics) == 1:
            ctx.ensure_banner()
            out_write(DATA["topics"]["selections"])
            return ctx.finish_success(0)
        sub = topics[1]
        key = f"selections {sub}"
        if key not in DATA["topics"]:
            return help_error(
                ctx, f"Help topic 'selections' has no subtopic '{sub}'")
        if len(topics) > 2:
            return help_error(
                ctx, f"Help topic 'selections {sub}' has no subtopics")
        ctx.ensure_banner()
        out_write(DATA["topics"][key])
        return ctx.finish_success(0)
    if first in COMMANDS:
        if len(topics) > 1:
            return help_error(ctx, f"Help topic '{first}' has no subtopics")
        ctx.ensure_banner()
        out_write(COMMANDS[first]["help"])
        return ctx.finish_success(0)
    return help_error(ctx, f"No help available for '{first}'")


def help_error(ctx, message):
    ctx.ensure_banner()
    err_write(message + "\n")
    if not ctx.common.get("quiet"):
        err_write(f"\nGROMACS reminds you: {ctx.quote_text()}\n\n")
    return 2


# ---------------------------------------------------------------------------
# Main dispatch
# ---------------------------------------------------------------------------

def sync_common(ctx, state):
    for name in ("h", "quiet", "version", "copyright", "nice", "backup", "debug"):
        if state.is_set(name):
            ctx.common[name] = state.values.get(name)
            ctx.common_set.add(name)


def main(argv=None):
    if argv is None:
        argv = sys.argv
    ctx = Context(argv)
    try:
        return run(ctx)
    except GmxError as e:
        return ctx.print_error(e)
    except BrokenPipeError:
        try:
            sys.stdout.close()
        except Exception:
            pass
        return 0


def run(ctx):
    args = ctx.args

    # --- locate the command name: first argument not starting with '-'
    cand_index = None
    for i, a in enumerate(args):
        if not a.startswith("-"):
            cand_index = i
            break
    pre_args = args if cand_index is None else args[:cand_index]
    candidate = None if cand_index is None else args[cand_index]
    post_args = [] if cand_index is None else args[cand_index + 1:]

    # --- parse the common options that precede the command
    cspecs = common_specs()
    pre_state = OptState(cspecs)
    positionals, segments = segment_args(pre_args)
    if positionals:
        # Partially parse so that a preceding -quiet is honoured.
        parse_segments(ctx, segments, cspecs, pre_state)
        sync_common(ctx, pre_state)
        raise positional_error(ctx, positionals[0], module_stage=False)
    pre_errors = parse_segments(ctx, segments, cspecs, pre_state)
    sync_common(ctx, pre_state)
    if pre_errors:
        raise invalid_options_error(ctx, pre_errors, module_stage=False)

    if ctx.common.get("version"):
        return print_version(ctx)
    if ctx.common.get("h"):
        return print_root_help(ctx)
    if candidate is None:
        return print_root_help(ctx)
    if candidate not in COMMANDS:
        raise GmxError(
            f"'{candidate}' is not a GROMACS command.\n",
            title="Error in user input:",
            source="src/gromacs/commandline/cmdlinemodulemanager.cpp", line=389,
            function=("gmx::ICommandLineModule* gmx::CommandLineModuleManager::Impl::"
                      "processCommonOptions(gmx::CommandLineCommonOptionsHolder*, int*, char***)"),
            module_stage=False,
        )

    cmd = candidate
    ctx.command = cmd
    ctx.display = f"gmx {cmd}"

    # --- first module phase: extract and validate common options anywhere
    specs = command_specs(cmd)
    all_specs = specs + [s for s in cspecs if s["name"] not in {x["name"] for x in specs}]
    state = OptState(all_specs)
    # Seed common values from the pre-command phase.
    for name, val in ctx.common.items():
        state.values[name] = val
    positionals, segments = segment_args(post_args)
    common_errors = parse_segments(
        ctx, segments, cspecs, state, only_common=True, common_spec_list=cspecs)
    sync_common(ctx, state)
    if common_errors:
        raise invalid_options_error(ctx, common_errors, module_stage=True)

    if ctx.common.get("version"):
        return print_version(ctx)
    if ctx.common.get("h"):
        ctx.ensure_banner()
        out_write(COMMANDS[cmd]["help"])
        return ctx.finish_success(0)

    # --- second phase: the module's own options
    if cmd == "help":
        # Any remaining option is unknown for the help module.
        other_segments = []
        for seg in segments:
            spec, _ = spec_lookup(cspecs, option_raw_name(seg.token))
            if spec is None:
                other_segments.append(seg)
        if other_segments:
            errs = parse_segments(ctx, other_segments, [], state)
            if errs:
                raise invalid_options_error(ctx, errs, module_stage=True)
        return run_help_module(ctx, positionals)

    if positionals:
        raise positional_error(ctx, positionals[0], module_stage=True)

    module_segments = []
    for seg in segments:
        spec, _ = spec_lookup(cspecs, option_raw_name(seg.token))
        if spec is None:
            module_segments.append(seg)
    errors = parse_segments(ctx, module_segments, specs, state)
    if errors:
        raise invalid_options_error(ctx, errors, module_stage=True)

    finish_options(ctx, cmd, specs, state)

    if cmd in TRAJECTORY_ANALYSIS_COMMANDS:
        if state.file_value("f") is None and state.file_value("s") is None:
            raise GmxError(
                "No trajectory or topology provided, nothing to do!\n",
                title="Inconsistency in user input:",
                source="src/gromacs/trajectoryanalysis/runnercommon.cpp", line=403,
                function="void gmx::TrajectoryAnalysisRunnerCommon::optionsFinished()",
                module_stage=True,
            )

    from .tools import dispatch_tool

    ctx.ensure_banner()
    return dispatch_tool(ctx, cmd, state)
