"""File format helpers shared by several tools."""

import math
import os
import time

from .main import GmxError, VERSION, DATA_PREFIX, byte_len, out_write
from .numerics import fmt_g

ACRONYMS = [
    "GROwing Monsters And Cloning Shrimps",
    "Good ROcking Metal Altar for Chronical Sinners",
    "Good gRace! Old Maple Actually Chews Slate",
]


def title_line(ctx):
    core = f":-) GROMACS - {ctx.display}, {VERSION} (-:"
    pad = max(1, (80 - byte_len(core)) // 2)
    return " " * pad + core


def xvg_header(ctx, title, xlabel, ylabel, legends, xvg_format,
               subtype=None, extra_at=None):
    if xvg_format == "none":
        return ""
    now = time.strftime("%a %b %e %H:%M:%S %Y", time.localtime())
    # %e is not portable in Python on every platform, but is on Linux;
    # normalise a possible literal %e just in case.
    if "%e" in now:
        now = now.replace("%e", f"{time.localtime().tm_mday:2d}")
    lines = []
    lines.append(f"# This file was created {now}")
    lines.append("# Created by:")
    lines.append("#" + title_line(ctx))
    lines.append("# ")
    ex = ctx.executable_path()
    if ex:
        lines.append(f"# Executable:   {ex}")
    lines.append(f"# Data prefix:  {DATA_PREFIX}")
    lines.append(f"# Working dir:  {ctx.cwd}")
    lines.append("# Command line:")
    lines.append(f"#   {ctx.command_line_text()}")
    lines.append(f"# {ctx.display} is part of G R O M A C S:")
    lines.append("#")
    import random
    acronym = random.Random(int(time.time())).choice(ACRONYMS)
    lines.append(f"# {acronym}")
    lines.append("#")
    if subtype is None:
        subtype = "xy" if xvg_format == "xmgrace" else "nxy"
    if title is not None:
        lines.append(f'@    title "{title}"')
    if xlabel is not None:
        lines.append(f'@    xaxis  label "{xlabel}"')
    if ylabel is not None:
        lines.append(f'@    yaxis  label "{ylabel}"')
    lines.append(f"@TYPE {subtype}")
    lines.append("@ view 0.15, 0.15, 0.75, 0.85")
    if legends:
        lines.append("@ legend on")
        lines.append("@ legend box on")
        lines.append("@ legend loctype view")
        lines.append("@ legend 0.78, 0.8")
        lines.append(f"@ legend length {len(legends)}")
        if xvg_format == "xmgr":
            for i, leg in enumerate(legends):
                lines.append(f'@ legend string {i} "{leg}"')
        else:
            for i, leg in enumerate(legends):
                lines.append(f'@ s{i} legend "{leg}"')
    if extra_at:
        lines.extend(extra_at)
    return "\n".join(lines) + ("\n" if lines else "")


def normalize_xvg_filename(filename):
    base = filename.rsplit("/", 1)[-1]
    ext = base.rsplit(".", 1)[-1].lower() if "." in base else ""
    if ext != "xvg":
        return filename + ".xvg"
    return filename


def file_io_error(filename):
    return GmxError(
        filename + "\n", title="File input/output error:",
        source="src/gromacs/utility/futil.cpp", line=414, function=None,
        module_stage=True,
    )


def write_xvg(ctx, filename, rows, *, title=None, xlabel=None, ylabel=None,
              legends=None, xvg_format="xmgrace", subtype=None):
    filename = normalize_xvg_filename(filename)
    text = xvg_header(ctx, title, xlabel, ylabel, legends or [], xvg_format,
                      subtype=subtype)
    for row in rows:
        parts = []
        for i, v in enumerate(row):
            parts.append(fmt_g(v, 10 if i == 0 else 12, 6))
        text += "".join(parts) + "\n"
    try:
        ctx.write_output_file(filename, text)
    except OSError:
        raise file_io_error(filename)
    return filename


def read_text_file(ctx, filename):
    """Read a text file, transparently handling a .gz companion."""
    import gzip

    candidates = [filename]
    if not os.path.exists(filename) and os.path.exists(filename + ".gz"):
        candidates = [filename + ".gz"]
    path = candidates[0]
    if path.endswith(".gz"):
        with gzip.open(path, "rt", encoding="utf-8", errors="surrogateescape") as fh:
            return fh.read()
    with open(path, "r", encoding="utf-8", errors="surrogateescape") as fh:
        return fh.read()
PYEOF
