"""Selection syntax validation.

This is a deliberately permissive validator: it recognises the common
selection grammar well enough to reproduce the reference parser's syntax
errors for plainly invalid input, while accepting the documented keyword
phrases, comparisons, boolean combinations and group references.
"""

import re

KEYWORD_PHRASES = {
    "name", "atomname", "resname", "type", "atomnr", "resnr", "resid",
    "resindex", "molindex", "chain", "insertioncode",
}
COORD_WORDS = {"x", "y", "z"}
SIMPLE_WORDS = {"all", "none"}


def _tokens(text):
    # Words, numbers, quoted strings, punctuation and comparison operators.
    return re.findall(r'"[^"]*"|\w+(?:\.\w+)?|<=|>=|==|!=|<|>|\(|\)|;|,', text)


def _error(original, near):
    return [
        (4, f"Invalid selection '{original}'"),
        (6, f"Near '{near}'"),
        (8, "syntax error"),
    ]


def validate_selection(text):
    """Return error details (list of (indent,msg)) or None when valid."""
    original = text
    for part in text.split(";"):
        s = part.strip()
        if not s:
