"""Small helpers emulating C float arithmetic and printf formatting."""

import math
import struct


def f32(x):
    try:
        return struct.unpack("f", struct.pack("f", float(x)))[0]
    except OverflowError:
        return math.copysign(math.inf, float(x))


def is_negative_number(x):
    return struct.pack(">d", float(x))[0] & 0x80 != 0


def _nan_text(x):
    return "-nan" if is_negative_number(x) else "nan"


def fmt_g(x, width=0, prec=6):
    if isinstance(x, float) and math.isnan(x):
        return _nan_text(x).rjust(width)
    return f"%{width}.{prec}g" % x if width else f"%.{prec}g" % x


def fmt_e(x, width=0, prec=5):
    if isinstance(x, float) and math.isnan(x):
        return _nan_text(x).rjust(width)
    return f"%{width}.{prec}e" % x if width else f"%.{prec}e" % x


def fmt_f(x, width=0, prec=5):
    if isinstance(x, float) and math.isnan(x):
        return _nan_text(x).rjust(width)
    return f"%{width}.{prec}f" % x if width else f"%.{prec}f" % x


def c_div(a, b):
    a = float(a); b = float(b)
    if b == 0.0:
        if a == 0.0 or math.isnan(a):
            return math.copysign(math.nan, -1.0)
        sign = math.copysign(1.0, a) * math.copysign(1.0, b)
        return math.copysign(math.inf, sign)
    return a / b


def c_pow(a, b):
    a = float(a); b = float(b)
    try:
        if a == 1.0 and math.isinf(b):
            return 1.0
        return math.pow(a, b)
    except ValueError:
        return math.copysign(math.nan, -1.0)
    except OverflowError:
        # math.pow overflow: sign is negative only for a negative base with
        # an odd integral exponent.
        neg = a < 0 and float(b).is_integer() and int(abs(b)) % 2 == 1
        return -math.inf if neg else math.inf


def f_pow(a, b):
    return f32(c_pow(a, b))


def f_exp(x):
    try:
        return f32(math.exp(float(x)))
    except OverflowError:
        return math.inf


def f_div(a, b):
    return f32(c_div(a, b))
