"""Implementations of individual gmx commands."""

import math
import os

from .main import GmxError, out_write, err_write, wrap_line
from .numerics import f32, f_pow, f_exp, f_div, c_div, c_pow, fmt_e, fmt_f, fmt_g
from .fileio import write_xvg

COULOMB = 138.9354558456  # 1/(4*pi*eps0) in GROMACS units


def _lj_potential(r, c6, cn, n, qq=0.0):
    v = c_div(cn, c_pow(r, n)) - c_div(c6, c_pow(r, 6))
    if qq:
        v += c_div(COULOMB * qq, r)
    return f32(v)


def _find_coulomb_minimum(c6, cn, n, qq, sigma):
    lo = max(sigma * 0.01, 1e-4) if sigma and sigma > 0 else 1e-3
    hi = max(sigma * 10.0, lo * 10) if sigma and sigma > 0 else 10.0
    # Scan in log space, then refine with a golden-section search.
    import math as _m

    def val(logr):
        return _lj_potential(_m.exp(logr), c6, cn, n, qq)

    npts = 400
    logs = [_m.log(lo) + (_m.log(hi) - _m.log(lo)) * i / (npts - 1) for i in range(npts)]
    vals = [val(x) for x in logs]
    i = min(range(npts), key=lambda k: vals[k])
    a = logs[max(0, i - 1)]
    b = logs[min(npts - 1, i + 1)]
    gr = (_m.sqrt(5) - 1) / 2
    c = b - gr * (b - a)
    d = a + gr * (b - a)
    for _ in range(200):
        if val(c) < val(d):
            b = d
        else:
            a = c
        c = b - gr * (b - a)
        d = a + gr * (b - a)
        if b - a < 1e-12:
            break
    r = _m.exp((a + b) / 2)
    return f32(r), _lj_potential(r, c6, cn, n, qq)


def tool_sigeps(ctx, state):
    def val(name):
        return state.value(name)

    n = int(val("pow"))
    qi = float(val("qi")); qj = float(val("qj"))
    qq = f32(qi * qj)
    buck_mode = any(state.is_set(k) for k in ("A", "B", "C"))
    sig_mode = any(state.is_set(k) for k in ("sig", "eps"))
    c_mode = any(state.is_set(k) for k in ("c6", "cn", "pow"))

    a_in = float(val("A")); b_in = float(val("B")); c_in = float(val("C"))

    rmin = 0.0
    if buck_mode:
        if n == 6:
            sigma = f_div(n, b_in)
        else:
            sigma = f32(f_div(n, b_in) * f_pow(f_div(6.0, n), f_div(1.0, n - 6)))
        epsilon = f_div(c_in, f32(4.0 * f_pow(sigma, 6)))
