import os, re, shutil, subprocess, sys

ORIG="/workspace/executable"; MINE="/tmp/myexe"

def setup(base, target):
    shutil.rmtree(base, ignore_errors=True); os.makedirs(base)
    os.symlink(target, os.path.join(base,"executable"))

def normalize(text, base):
    text=text.replace(base,"<WD>")
    text=re.sub(r"(?m)^Executable:   .*$","Executable:   <EXE>",text)
    text=re.sub(r"(?m)^# Executable:   .*$","# Executable:   <EXE>",text)
    text=re.sub(r"(?m)^GROMACS reminds you: .*$","GROMACS reminds you: <QUOTE>",text)
    text=re.sub(r"(?m)^# This file was created .*$","# This file was created <TIME>",text)
    lines=text.splitlines(True)
    # acronym line after G R O M A C S:
    out=[]
    for i,l in enumerate(lines):
        if i>1 and "is part of G R O M A C S:" in lines[i-2] if i>=2 else False:
            pass
        out.append(l)
    text="".join(out)
    # Replace acronym heuristically: line after '#\n' following GROMACS line (handled below in file compare)
    return text

def norm_file(data, base):
    try:text=data.decode()
    except:return data
    text=normalize(text,base)
    # acronym: the line two after "is part of"
    ls=text.splitlines(True)
    for i,l in enumerate(ls):
        if "is part of G R O M A C S:" in l and i+2<len(ls):
            ls[i+2]="# <ACRONYM>\n"
    return "".join(ls).encode()

def run_case(args, files=None, stdin=""):
    files=files or {}
    results=[]
    for label,target,base in [("orig",ORIG,"/tmp/cmp_orig"),("mine",MINE,"/tmp/cmp_mine")]:
        setup(base,target)
        for name,content in files.items():
            path=os.path.join(base,name)
            os.makedirs(os.path.dirname(path),exist_ok=True) if os.path.dirname(name) else None
            mode="wb" if isinstance(content,bytes) else "w"
            with open(path,mode) as f:f.write(content)
        p=subprocess.run(["./executable"]+args,capture_output=True,text=True,cwd=base,input=stdin,timeout=20)
        created={}
        for root,dirs,fs in os.walk(base):
            for fn in fs:
                rel=os.path.relpath(os.path.join(root,fn),base)
                if rel=="executable": continue
                if rel in files: continue
                created[rel]=open(os.path.join(root,fn),"rb").read()
        results.append((p.returncode,normalize(p.stdout,base),normalize(p.stderr,base),
                        {k:norm_file(v,base) for k,v in created.items()}))
    ok=results[0]==results[1]
    print(("OK  " if ok else "FAIL"),args)
    if not ok:
        for i,name in enumerate(["exit","stdout","stderr","files"]):
            if results[0][i]!=results[1][i]:
                print(f"--- {name} orig ---\n{results[0][i]!r}\n--- {name} mine ---\n{results[1][i]!r}")
    return ok

