"""Readers and writers for the text structure/trajectory formats.

Coordinates are stored in nm, as in GROMACS.  Values read from files are
kept at single precision to mirror the reference (mixed precision) build.
"""

import gzip
import math
import os

from .main import GmxError
from .numerics import f32
from .library import require_library_file, find_library_file


class Atom:
    __slots__ = ("resnr", "resname", "atomname", "atomnr", "pos", "vel",
                 "chain", "occupancy", "bfactor", "element", "record")

