                 chain="", occupancy=1.0, bfactor=0.0, element="",
                 record="ATOM"):
        self.resnr = int(resnr)
        self.resname = resname
        self.atomname = atomname
        self.atomnr = int(atomnr)
        self.pos = tuple(f32(x) for x in pos)
        self.vel = tuple(f32(x) for x in vel) if vel is not None else None
        self.chain = chain
        self.occupancy = float(occupancy)
        self.bfactor = float(bfactor)
