STRUCTURE_EXTS = {"gro", "g96", "pdb", "brk", "ent", "esp"}


def read_frames(filename):
    ext = file_extension(filename)
    if ext == "gro":
        return read_gro(filename)
    if ext == "g96":
        return read_g96(filename)
    if ext in ("pdb", "brk", "ent", "esp"):
        return read_pdb(filename)
    if ext == "tpr":
        from .tpr import read_tpr_frames
        return read_tpr_frames(filename)
    raise GmxError(
        f"File '{filename}' has an unsupported type.\n", title="Fatal error:",
        source="src/gromacs/fileio/confio.cpp", line=1, function=None)


def read_structure(ctx, filename, *, need_residuetypes=True,
                   need_atommas=False):
    """Read a structure as a topology-bearing file (first frame)."""
    if need_residuetypes and file_extension(filename) != "tpr":
        require_library_file(ctx, "residuetypes.dat")
    frames = read_frames(filename)
    if need_atommas and file_extension(filename) != "tpr":
        require_library_file(ctx, "atommass.dat")
    if not frames:
        raise GmxError(
            f"No atoms found in file '{filename}'.\n", title="Fatal error:",
            source="src/gromacs/fileio/confio.cpp", line=1, function=None)
    return frames[0], frames


def residue_types(ctx):
    path = find_library_file(ctx, "residuetypes.dat")
    types = {}
    if path is None:
        return types
    try:
        for line in read_lines(path):
            parts = line.split()
            if len(parts) >= 2:
                types[parts[0]] = parts[1]
    except OSError:
        pass
    return types


def write_structure(ctx, filename, frame):
    ext = file_extension(filename)
    if ext == "gro":
        text = format_gro(frame)
    elif ext == "g96":
        text = format_g96(frame)
    elif ext in ("pdb", "brk", "ent", "esp"):
        text = format_pdb(frame)
    else:
        raise GmxError(
            f"File '{filename}' has an unsupported type.\n",
            title="Fatal error:", source="src/gromacs/fileio/confio.cpp",
            line=1, function=None)
    ctx.write_output_file(filename, text)
