def cell_to_box(a, b, c, alpha, beta, gamma):
    """Crystallographic cell (nm, degrees) to box matrix."""
    al, be, ga = (math.radians(x) for x in (alpha, beta, gamma))
    ax = a
    bx = b * math.cos(ga)
    by = b * math.sin(ga)
    cx = c * math.cos(be)
    cy = c * (math.cos(al) - math.cos(be) * math.cos(ga)) / math.sin(ga) if math.sin(ga) else 0.0
    cz2 = c * c - cx * cx - cy * cy
    cz = math.sqrt(cz2) if cz2 > 0 else 0.0
    return ((f32(ax), 0.0, 0.0), (f32(bx), f32(by), 0.0),
            (f32(cx), f32(cy), f32(cz)))


