"""Index groups: .ndx parsing, default groups and interactive prompts."""

import re
import sys

from .main import GmxError, out_write, err_write
from .structures import read_lines, residue_types


class Group:
    def __init__(self, name, indices):
        self.name = name
        self.indices = list(indices)  # zero based


def parse_ndx(filename):
    groups = []
    current = None
    for line in read_lines(filename):
        s = line.strip()
        m = re.match(r"\[\s*(.*?)\s*\]", s)
        if m:
            current = Group(m.group(1), [])
            groups.append(current)
            continue
        if current is None or not s or s.startswith(";"):
            continue
        for tok in s.split():
            try:
                current.indices.append(int(tok) - 1)
            except ValueError:
                pass
    return groups


def format_ndx(groups):
    out = []
    for g in groups:
        out.append(f"[ {g.name} ]")
        idx = [i + 1 for i in g.indices]
        for k in range(0, len(idx), 15):
            out.append("".join(f"{v:4d}" for v in idx[k:k + 15]))
    return "\n".join(out) + "\n" if out else ""


def _is_hydrogen(atom):
    name = atom.atomname.lstrip("0123456789")
    return name[:1].upper() == "H" and name[:2].upper() not in ("HG", "HF")


def default_groups(ctx, frame):
    rtypes = residue_types(ctx)
    atoms = frame.atoms

    def residue_type(atom):
        return rtypes.get(atom.resname, "Other")

    groups = [Group("System", range(len(atoms)))]
    protein = [i for i, a in enumerate(atoms) if residue_type(a) == "Protein"]
    if protein:
        main_names = {"N", "CA", "C", "O"}
        backbone = [i for i in protein if atoms[i].atomname in {"N", "CA", "C"}]
        mainchain = [i for i in protein if atoms[i].atomname in main_names]
        groups.append(Group("Protein", protein))
        groups.append(Group("Protein-H",
                            [i for i in protein if not _is_hydrogen(atoms[i])]))
        groups.append(Group("C-alpha",
                            [i for i in protein if atoms[i].atomname == "CA"]))
        groups.append(Group("Backbone", backbone))
        groups.append(Group("MainChain", mainchain))
        groups.append(Group("MainChain+Cb",
                            [i for i in protein if atoms[i].atomname in main_names | {"CB"}]))
        groups.append(Group("MainChain+H",
                            [i for i in protein if atoms[i].atomname in main_names or _is_hydrogen(atoms[i])]))
        side = [i for i in protein if i not in set(mainchain)]
        groups.append(Group("SideChain", side))
        groups.append(Group("SideChain-H",
                            [i for i in side if not _is_hydrogen(atoms[i])]))
    dna = [i for i, a in enumerate(atoms) if residue_type(a) == "DNA"]
    if dna:
        groups.append(Group("DNA", dna))
        groups.append(Group("DNA-H", [i for i in dna if not _is_hydrogen(atoms[i])]))
    rna = [i for i, a in enumerate(atoms) if residue_type(a) == "RNA"]
    if rna:
        groups.append(Group("RNA", rna))
        groups.append(Group("RNA-H", [i for i in rna if not _is_hydrogen(atoms[i])]))
    if protein and len(protein) < len(atoms):
        groups.append(Group("Non-Protein",
                            [i for i in range(len(atoms)) if i not in set(protein)]))
    water = [i for i, a in enumerate(atoms) if residue_type(a) == "Water"]
    if water:
        groups.append(Group("Water", water))
    ions = [i for i, a in enumerate(atoms) if residue_type(a) == "Ion"]
    if ions:
        groups.append(Group("Ion", ions))
    other = [i for i, a in enumerate(atoms) if residue_type(a) not in
             ("Protein", "DNA", "RNA", "Water", "Ion")]
    if other:
        groups.append(Group("Other", other))
        seen = []
        for i in other:
            rn = atoms[i].resname
            if rn not in seen:
                seen.append(rn)
        for rn in seen:
            groups.append(Group(rn, [i for i in other if atoms[i].resname == rn]))
    return groups


def prompt_group(ctx, groups, heading):
    err_write("\n" + heading + "\n")
    for i, g in enumerate(groups):
        err_write(f"Group {i:5d} ({g.name:>15s}) has {len(g.indices):5d} elements\n")
    while True:
        err_write("Select a group: ")
        try:
            sys.stderr.buffer.flush()
        except Exception:
            pass
        line = sys.stdin.readline()
        if line == "":
            raise GmxError(
                "Cannot read from input\n", title="Fatal error:",
                source="src/gromacs/topology/index.cpp", line=874,
                function=None, module_stage=True)
        answer = line.strip()
        chosen = None
        if answer.isdigit():
            k = int(answer)
            if 0 <= k < len(groups):
                chosen = k
        if chosen is None:
            for i, g in enumerate(groups):
                if g.name == answer:
                    chosen = i
                    break
        if chosen is None:
            out_write(f"Error: No such group '{answer}'\n")
            continue
        out_write(f"Selected {chosen}: '{groups[chosen].name}'\n")
        return groups[chosen]
