"""Principal-axis alignment used by editconf -princ / -align."""

import math

from .masses import guess_masses
from .numerics import f32


def _jacobi_eigen(matrix):
    a = [row[:] for row in matrix]
    v = [[1.0 if i == j else 0.0 for j in range(3)] for i in range(3)]
    for _ in range(100):
        off = math.sqrt(a[0][1] ** 2 + a[0][2] ** 2 + a[1][2] ** 2)
        if off < 1e-15:
            break
        for p, q in ((0, 1), (0, 2), (1, 2)):
            if abs(a[p][q]) < 1e-300:
                continue
            theta = 0.5 * math.atan2(2 * a[p][q], a[p][p] - a[q][q]) if a[p][p] != a[q][q] else math.pi / 4
            c, s = math.cos(theta), math.sin(theta)
            for k in range(3):
                akp = c * a[k][p] - s * a[k][q]
                akq = s * a[k][p] + c * a[k][q]
                a[k][p], a[k][q] = akp, akq
            for k in range(3):
                apk = c * a[p][k] - s * a[q][k]
                aqk = s * a[p][k] + c * a[q][k]
                a[p][k], a[q][k] = apk, aqk
            for k in range(3):
                vkp = c * v[k][p] - s * v[k][q]
                vkq = s * v[k][p] + c * v[k][q]
                v[k][p], v[k][q] = vkp, vkq
    vals = [a[i][i] for i in range(3)]
    vecs = [[v[i][j] for i in range(3)] for j in range(3)]
    return vals, vecs


def _principal_axes(ctx, frame, indices):
    masses = guess_masses(ctx, frame.atoms)
    total = sum(masses[i] for i in indices) or float(len(indices))
    weights = [(masses[i] if total and masses[i] else 1.0) for i in indices]
    wsum = sum(weights)
    com = [sum(weights[k] * frame.atoms[indices[k]].pos[d] for k in range(len(indices))) / wsum
           for d in range(3)]
    cov = [[0.0] * 3 for _ in range(3)]
    for k, i in enumerate(indices):
        r = [frame.atoms[i].pos[d] - com[d] for d in range(3)]
        for a in range(3):
            for b in range(3):
                cov[a][b] += weights[k] * r[a] * r[b]
    vals, vecs = _jacobi_eigen(cov)
    order = sorted(range(3), key=lambda i: -vals[i])
    axes = []
    for oi in order:
        vec = vecs[oi]
        norm = math.sqrt(sum(x * x for x in vec)) or 1.0
        axes.append([x / norm for x in vec])
    # Make a right-handed set.
    cross = [
        axes[0][1] * axes[1][2] - axes[0][2] * axes[1][1],
        axes[0][2] * axes[1][0] - axes[0][0] * axes[1][2],
        axes[0][0] * axes[1][1] - axes[0][1] * axes[1][0],
    ]
    if sum(cross[i] * axes[2][i] for i in range(3)) < 0:
        axes[2] = [-x for x in axes[2]]
    return axes, com


def align_principal_axes(ctx, frame, indices):
    axes, _com = _principal_axes(ctx, frame, indices)
    # New coordinates are the projections onto the principal axes.
    for a in frame.atoms:
        a.pos = tuple(f32(sum(a.pos[d] * axes[k][d] for d in range(3)))
                      for k in range(3))
        if a.vel is not None:
            a.vel = tuple(f32(sum(a.vel[d] * axes[k][d] for d in range(3)))
                          for k in range(3))


def align_to_vector(ctx, frame, indices, target, center):
    axes, _com = _principal_axes(ctx, frame, indices)
    axis = axes[0]
    t = [float(x) for x in target]
    norm = math.sqrt(sum(x * x for x in t))
    if norm == 0:
        return
    t = [x / norm for x in t]
    # Rodrigues rotation from axis to target about the given centre.
    cross = [axis[1] * t[2] - axis[2] * t[1],
             axis[2] * t[0] - axis[0] * t[2],
             axis[0] * t[1] - axis[1] * t[0]]
    s = math.sqrt(sum(x * x for x in cross))
    c = sum(axis[i] * t[i] for i in range(3))
    if s < 1e-12:
        return
    k = [x / s for x in cross]
    cen = [float(x) for x in center]

    def rot(p):
        r = [p[i] - cen[i] for i in range(3)]
        term1 = [r[i] * c for i in range(3)]
        term2 = [k[1] * r[2] - k[2] * r[1], k[2] * r[0] - k[0] * r[2],
                 k[0] * r[1] - k[1] * r[0]]
        kd = sum(k[i] * r[i] for i in range(3))
        out = [cen[i] + term1[i] + s * term2[i] + k[i] * kd * (1 - c)
               for i in range(3)]
        return tuple(f32(x) for x in out)

    for a in frame.atoms:
        a.pos = rot(a.pos)
