"""Atomic masses: from atommass.dat when present, else guessed by element."""

import re

from .library import find_library_file
from .structures import read_lines

ELEMENT_MASSES = {
    "H": 1.00794, "HE": 4.002602, "LI": 6.941, "BE": 9.012182, "B": 10.811,
    "C": 12.0107, "N": 14.0067, "O": 15.9994, "F": 18.9984032, "NE": 20.1797,
    "NA": 22.98977, "MG": 24.305, "AL": 26.9815386, "SI": 28.0855,
    "P": 30.973762, "S": 32.065, "CL": 35.453, "AR": 39.948, "K": 39.0983,
    "CA": 40.078, "MN": 54.938045, "FE": 55.845, "CO": 58.933195,
    "NI": 58.6934, "CU": 63.546, "ZN": 65.38, "BR": 79.904, "I": 126.90447,
    "D": 2.01410178,
}
# Atom names whose leading letters are not the element symbol.
_NAME_ELEMENTS = {
    "CA": "C", "CB": "C", "CG": "C", "CD": "C", "CE": "C", "CZ": "C",
    "CH": "C", "N": "N", "O": "O",
}


def element_of(atom):
    if atom.element:
        return atom.element.strip().upper()
    name = atom.atomname.strip().lstrip("0123456789")
    up = name.upper()
    if up in _NAME_ELEMENTS and atom.resname.upper() not in ("CA", "CAL"):
        # In a protein residue, CA/CB/... are carbons; for a calcium ion
        # residue the resname check above keeps Ca.  This heuristic is only
        # used when no element information is available.
        if len(up) >= 2 and up[:2] in _NAME_ELEMENTS:
            return _NAME_ELEMENTS[up[:2]]
    m = re.match(r"([A-Za-z]{1,2})", name)
    if not m:
        return ""
    two = m.group(1).upper()
    if len(two) == 2 and two in ELEMENT_MASSES:
        # Prefer a two-letter element only for known ion-like names.
        if two in ("NA", "CL", "MG", "ZN", "FE", "CU", "MN", "BR", "SI", "AL", "CA", "NI", "CO", "HE", "LI", "BE", "NE", "AR"):
            return two
    return two[:1]


def _atommass_table(ctx):
    path = find_library_file(ctx, "atommass.dat")
    table = {}
    if path is None:
        return table
    try:
        for line in read_lines(path):
            parts = line.split()
            if len(parts) >= 2:
                try:
                    table[parts[0].upper()] = float(parts[1])
                except ValueError:
                    pass
    except OSError:
        pass
    return table


def guess_masses(ctx, atoms):
    table = _atommass_table(ctx)
    masses = []
    for a in atoms:
        el = element_of(a)
        if el in table:
            masses.append(table[el])
        else:
            masses.append(ELEMENT_MASSES.get(el, 0.0))
    return masses
