"""Implementation of ``gmx make_ndx`` (the index group editor)."""

import fnmatch
import math
import re
import sys

from .main import GmxError, out_write, err_write
from .structures import read_frames, Frame
from .groups import (
    Group, parse_ndx, format_ndx, default_groups, residue_instances,
    residue_type_counts,
)
from .library import require_library_file

COMMAND_TABLE = """ nr : group      '!': not  'name' nr name   'splitch' nr    Enter: list groups
 'a': atom       '&': and  'del' nr         'splitres' nr   'l': list residues
 't': atom type  '|': or   'keep' nr        'splitat' nr    'h': help
 'r': residue              'res' nr         'chain' char
 "name": group             'case': case sensitive           'q': save and quit
 'ri': residue index
"""

HELP_TEXT = """ nr                : selects an index group by number or quoted string.
                     The string is first matched against the whole group name,
                     then against the beginning and finally against an
                     arbitrary substring. A multiple match is an error.
 'a' nr1 [nr2 ...] : selects atoms, atom numbering starts at 1.
 'a' nr1 - nr2     : selects atoms in the range from nr1 to nr2.
 'a' name1[*] [name2[*] ...] : selects atoms by name(s), '?' matches any char,
                               wildcard '*' allowed at the end of a name.
 't' type1[*] [type2[*] ...] : as 'a', but for type, run input file required.
 'r' nr1[ic1] [nr2[ic2] ...] : selects residues by number and insertion code.
 'r' nr1 - nr2               : selects residues in the range from nr1 to nr2.
 'r' name1[*] [name2[*] ...] : as 'a', but for residue names.
 'ri' nr1 - nr2              : selects residue indices, 1-indexed, (as opposed to numbers) in the range from nr1 to nr2.
 'chain' ch1 [ch2 ...]       : selects atoms by chain identifier(s),
                               not available with a .gro file as input.
 !                 : takes the complement of a group with respect to all
                     the atoms in the input file.
 & |               : AND and OR, can be placed between any of the options
                     above, the input is processed from left to right.
 'name' nr name    : rename group nr to name.
 'del' nr1 [- nr2] : deletes one group or groups in the range from nr1 to nr2.
 'keep' nr         : deletes all groups except nr.
 'case'            : make all name compares case (in)sensitive.
 'splitch' nr      : split group into chains using CA distances.
 'splitres' nr     : split group into residues.
 'splitat' nr      : split group into atoms.
 'res' nr          : interpret numbers in group as residue numbers
 Enter             : list the currently defined groups and commands
 'l'               : list the residues.
 'h'               : show this help.
 'q'               : save and quit.

 Examples:
 > 2 | 4 & r 3-5
 selects all atoms from group 2 and 4 that have residue numbers 3, 4 or 5
 > a C* & !a C CA
 selects all atoms starting with 'C' but not the atoms 'C' and 'CA'
 > "protein" & ! "backb"
 selects all atoms that are in group 'protein' and not in group 'backbone'
"""


def _print_groups(groups):
    out_write("\n")
    for i, g in enumerate(groups):
        out_write(f"{i:3d} {g.name:<20s}: {len(g.indices):5d} atoms\n")
    out_write("\n")
    out_write(COMMAND_TABLE)


class _Syntax(Exception):
    def __init__(self, token):
        self.token = token


class Editor:
    def __init__(self, ctx, frame, groups, natoms):
        self.ctx = ctx
        self.frame = frame
        self.groups = groups
        self.natoms = natoms
        self.case_sensitive = False
        self.residues = residue_instances(frame) if frame is not None else []

    # ----- matching helpers -------------------------------------------------
    def _match(self, pattern, text):
        if not self.case_sensitive:
            pattern, text = pattern.lower(), text.lower()
        regex = ""
        for ch in pattern:
            if ch == "?":
                regex += "."
            elif ch == "*":
                regex += ".*"
            else:
                regex += re.escape(ch)
        return re.fullmatch(regex, text) is not None

    def _find_group_by_name(self, name):
        def key(s):
            return s if self.case_sensitive else s.lower()

        target = key(name)
        for mode in ("exact", "prefix", "substring"):
            found = []
            for i, g in enumerate(self.groups):
                gn = key(g.name)
                if mode == "exact" and gn == target:
                    found.append(i)
                elif mode == "prefix" and gn.startswith(target):
                    found.append(i)
                elif mode == "substring" and target in gn:
                    found.append(i)
            if len(found) == 1:
                return found[0]
            if len(found) > 1:
                return None
        return None

    # ----- term evaluation ----------------------------------------------------
    def _eval_atom_specs(self, specs):
        indices = set()
        names = []
        i = 0
        atoms = self.frame.atoms if self.frame else []
        while i < len(specs):
            tok = specs[i]
            m = re.fullmatch(r"(\d+)-(\d+)", tok)
            range_pair = None
            if m:
                range_pair = (int(m.group(1)), int(m.group(2)))
            elif (tok.isdigit() and i + 2 < len(specs) and specs[i + 1] == "-"
                  and specs[i + 2].isdigit()):
                range_pair = (int(tok), int(specs[i + 2]))
                i += 2
            if range_pair is not None:
                a, b = range_pair
                found = [x - 1 for x in range(a, b + 1) if 1 <= x <= self.natoms]
                indices.update(found)
                out_write(f"Found {len(found)} atoms in range {a}-{b}\n")
                names.append(f"a_{a}-{b}")
            elif tok.isdigit():
                v = int(tok)
                if 1 <= v <= self.natoms:
                    indices.add(v - 1)
                names.append(f"a_{v}")
            else:
                found = [k for k, at in enumerate(atoms)
                         if self._match(tok, at.atomname)]
                indices.update(found)
                out_write(f"Found {len(found)} atoms with name {tok}\n")
                names.append(tok)
            i += 1
        return indices, "_".join(names)

    def _eval_res_specs(self, specs, by_index=False):
        indices = set()
        names = []
        i = 0
        prefix = "ri" if by_index else "r"
        while i < len(specs):
            tok = specs[i]
            m = re.fullmatch(r"(\d+)-(\d+)", tok)
            range_pair = None
            if m:
                range_pair = (int(m.group(1)), int(m.group(2)))
            elif (re.fullmatch(r"\d+[A-Za-z]?", tok) and i + 2 < len(specs)
                  and specs[i + 1] == "-" and re.fullmatch(r"\d+[A-Za-z]?", specs[i + 2])):
                range_pair = (int(re.match(r"\d+", tok).group()),
                              int(re.match(r"\d+", specs[i + 2]).group()))
                i += 2
            if range_pair is not None:
                a, b = range_pair
                for ri, ((resnr, _rn, _ch), ats) in enumerate(self.residues):
                    key = ri + 1 if by_index else resnr
                    if a <= key <= b:
                        indices.update(ats)
                names.append(f"{prefix}_{a}-{b}")
            elif re.fullmatch(r"\d+[A-Za-z]?", tok):
                v = int(re.match(r"\d+", tok).group())
                for ri, ((resnr, _rn, _ch), ats) in enumerate(self.residues):
                    key = ri + 1 if by_index else resnr
                    if key == v:
                        indices.update(ats)
                names.append(f"{prefix}_{tok}")
            else:
                if by_index:
                    raise _Syntax(tok)
                found = []
                for (_resnr, resname, _ch), ats in self.residues:
                    if self._match(tok, resname):
                        found.extend(ats)
                indices.update(found)
                out_write(f"Found {len(found)} atoms with residue name {tok}\n")
                names.append(tok)
            i += 1
        return indices, "_".join(names)

    def _eval_term(self, tokens, pos):
        if pos >= len(tokens):
            raise _Syntax(tokens[-1] if tokens else "")
        tok = tokens[pos]
        if tok.isdigit():
            k = int(tok)
            if not (0 <= k < len(self.groups)):
                raise _Syntax(tok)
            g = self.groups[k]
            out_write(f"Copied index group {k} '{g.name}'\n")
            return set(g.indices), g.name, pos + 1
        if tok.startswith('"') and tok.endswith('"') and len(tok) >= 2:
            k = self._find_group_by_name(tok[1:-1])
            if k is None:
                raise _Syntax(tok)
            g = self.groups[k]
            out_write(f"Copied index group {k} '{g.name}'\n")
            return set(g.indices), g.name, pos + 1
        low = tok.lower()
        if low in ("a", "r", "ri", "t", "chain"):
            specs = []
            j = pos + 1
            while j < len(tokens) and tokens[j] not in ("&", "|"):
                specs.append(tokens[j]); j += 1
            if not specs:
                raise _Syntax(tok)
            if low == "a":
                idx, name = self._eval_atom_specs(specs)
                return idx, name, j
            if low == "r":
                idx, name = self._eval_res_specs(specs)
                return idx, name, j
            if low == "ri":
                idx, name = self._eval_res_specs(specs, by_index=True)
                return idx, name, j
            if low == "t":
                out_write("Need a run input file to select atom types\n")
                return set(), "t", j
            if low == "chain":
                atoms = self.frame.atoms if self.frame else []
                found = set()
                names = []
                for sp in specs:
                    f = [k for k, at in enumerate(atoms)
                         if at.chain == sp]
                    found.update(f)
                    out_write(f"Found {len(f)} atoms with chain identifier {sp}\n")
                    names.append(sp)
                return found, "_".join(names), j
        raise _Syntax(tok)

    def eval_expression(self, line):
        tokens = re.findall(r'"[^"]*"|[&|!]|[^\s&|!]+', line)
        if not tokens:
            return
        result = None
        result_name = ""
        pending = None
        pos = 0
        expect_term = True
        while pos < len(tokens):
            if expect_term:
                neg = False
                if tokens[pos] == "!":
                    neg = True
                    pos += 1
                    if pos >= len(tokens):
                        raise _Syntax("!")
                idx, name, pos = self._eval_term(tokens, pos)
                if neg:
                    idx = set(range(self.natoms)) - idx
                    out_write(f"Complemented group: {len(idx)} atoms\n")
                    name = "!" + name
                if result is None:
                    result, result_name = idx, name
                else:
                    left, right = len(result), len(idx)
                    if pending == "&":
                        result &= idx
                        out_write(f"Merged two groups with AND: {left} {right} -> {len(result)}\n")
                    else:
                        result |= idx
                        out_write(f"Merged two groups with OR: {left} {right} -> {len(result)}\n")
                    result_name = f"{result_name}_{pending}_{name}"
                expect_term = False
            else:
                if tokens[pos] in ("&", "|"):
                    pending = tokens[pos]
                    pos += 1
                    expect_term = True
                else:
                    raise _Syntax(tokens[pos])
        if expect_term:
            raise _Syntax(tokens[-1])
        if not result:
            out_write("Group is empty\n")
            return
        self.groups.append(Group(result_name, sorted(result)))

    # ----- editor commands ----------------------------------------------------
    def _group_index_arg(self, arg):
        try:
            k = int(arg)
        except ValueError:
            raise _Syntax(arg)
        if not (0 <= k < len(self.groups)):
            raise _Syntax(arg)
        return k

    def command(self, line):
        """Returns True to continue editing."""
        stripped = line.strip()
        if stripped == "":
            _print_groups(self.groups)
            return True
        words = stripped.split()
        head = words[0].lower()
        try:
            if head in ("h", "help"):
                out_write(HELP_TEXT)
            elif head == "l":
                self._list_residues()
            elif head == "case":
                self.case_sensitive = not self.case_sensitive
                out_write("Switched to case sensitive\n" if self.case_sensitive
                          else "Switched to case insensitive\n")
            elif head == "name" and len(words) >= 3:
                k = self._group_index_arg(words[1])
                self.groups[k].name = words[2]
            elif head == "del" and len(words) >= 2:
                self._delete(words[1:])
            elif head == "keep" and len(words) >= 2:
                k = self._group_index_arg(words[1])
                kept = self.groups[k]
                for i, g in enumerate(self.groups):
                    if i != k:
                        out_write(f"Removed group {i} '{g.name}'\n")
                self.groups = [kept]
            elif head == "splitres" and len(words) >= 2:
                self._split_res(words[1])
            elif head == "splitat" and len(words) >= 2:
                self._split_at(words[1])
            elif head == "splitch" and len(words) >= 2:
                self._split_ch(words[1])
            elif head == "res" and len(words) >= 2:
                self._res(words[1])
            else:
                self.eval_expression(stripped)
        except _Syntax as e:
            out_write(f"\nSyntax error: \"{e.token}\"\n")
        return True

    def _list_residues(self):
        if not self.residues:
            return
        parts = []
        for (resnr, resname, _ch), _ats in self.residues:
            parts.append(f"{resnr:4d} {resname:<4s} ")
        # The reference lists residues in columns; with few residues this
        # is a single line.
        line = ""
        for p in parts:
            if len(line) + len(p) > 78 and line:
                out_write(line + "\n")
                line = ""
            line += p
        if line:
            out_write(line + "\n")

    def _delete(self, args):
        # args: nr  |  nr1 - nr2  |  nr1-nr2
        toks = " ".join(args).replace("-", " - ").split()
        if len(toks) == 1:
            ks = [self._group_index_arg(toks[0])]
        elif len(toks) == 3 and toks[1] == "-":
            a = self._group_index_arg(toks[0]); b = self._group_index_arg(toks[2])
            ks = list(range(a, b + 1))
        else:
            raise _Syntax(args[0] if args else "del")
        removed = [(k, self.groups[k].name) for k in ks]
        for k in sorted(ks, reverse=True):
            del self.groups[k]
        for k, nm in removed:
            out_write(f"Removed group {k} '{nm}'\n")

    def _split_res(self, arg):
        k = self._group_index_arg(arg)
        g = self.groups[k]
        out_write(f"Splitting group {k} '{g.name}' into residues\n")
        sel = set(g.indices)
        for (resnr, resname, _ch), ats in self.residues:
            sub = [i for i in ats if i in sel]
            if sub:
                self.groups.append(
                    Group(f"{g.name}_{resname}_{resnr}", sub))

    def _split_at(self, arg):
        k = self._group_index_arg(arg)
        g = self.groups[k]
        out_write(f"Splitting group {k} '{g.name}' into atoms\n")
        for i in g.indices:
            a = self.frame.atoms[i]
            self.groups.append(Group(f"{g.name}_{a.atomname}_{i + 1}", [i]))

    def _split_ch(self, arg):
        k = self._group_index_arg(arg)
        g = self.groups[k]
        # Split by chain identifier when available, otherwise by large
        # jumps between successive CA atoms.
        atoms = self.frame.atoms if self.frame else []
        chains = []
        sel = [i for i in g.indices if i < len(atoms)]
        if sel and any(atoms[i].chain.strip() for i in sel):
            order = []
            for i in sel:
                ch = atoms[i].chain
                if not order or order[-1][0] != ch:
                    order.append((ch, []))
                order[-1][1].append(i)
            chains = [c[1] for c in order]
        else:
            cas = [i for i in sel if atoms[i].atomname == "CA"]
            bounds = []
            for a, b in zip(cas, cas[1:]):
                d = math.sqrt(sum((atoms[a].pos[t] - atoms[b].pos[t]) ** 2
                                  for t in range(3)))
                if d > 0.45:
                    bounds.append(b)
            if bounds:
                cur = []
                bset = set(bounds)
                for i in sel:
                    if i in bset and cur:
                        chains.append(cur); cur = []
                    cur.append(i)
                if cur:
                    chains.append(cur)
            else:
                chains = [sel] if sel else []
        if len(chains) <= 1:
            if sel:
                out_write("Found 1 chain, will not split\n")
                out_write(f"1: {len(sel):5d} atoms ({sel[0] + 1} to {sel[-1] + 1})\n")
            return
        out_write(f"Found {len(chains)} chains\n")
        for ci, ch in enumerate(chains, 1):
            out_write(f"{ci}: {len(ch):5d} atoms ({ch[0] + 1} to {ch[-1] + 1})\n")
            self.groups.append(Group(f"{g.name}_chain{ci}", ch))

    def _res(self, arg):
        k = self._group_index_arg(arg)
        g = self.groups[k]
        nres = len(self.residues)
        result = set()
        n_found_res = 0
        for v in g.indices:
            rn = v + 1
            if rn > nres:
                out_write(f"Index {g.name} contains number>nres ({rn}>{nres})\n")
                out_write("Group is empty\n")
                return
            if rn >= 1:
                result.update(self.residues[rn - 1][1])
                n_found_res += 1
        out_write(f"Found {len(result)} atoms in {n_found_res} residues from group {g.name}\n")
        if result:
            self.groups.append(Group(f"atom_{g.name}", sorted(result)))


def tool_make_ndx(ctx, state):
    struct_file = state.file_value("f")
    index_files = []
    if state.is_set("n"):
        index_files = state.file_values("n")
    frame = None
    if struct_file is not None:
        err_write("\nReading structure file\n")
        frames = read_frames(struct_file)
        frame = frames[0] if frames else Frame()

    if struct_file is None and not index_files:
        raise GmxError(
            "No input files (structure or index)\n", title="Fatal error:",
            source="src/gromacs/tools/make_ndx.cpp", line=1478,
            function=None, module_stage=True)

    out_write(f"Going to read {len(index_files)} old index file(s)\n")

    if index_files:
        groups = []
        for fn in index_files:
            groups.extend(parse_ndx(fn))
        if frame is not None:
            natoms = len(frame.atoms)
        elif state.value("natoms"):
            natoms = int(state.value("natoms"))
        else:
            natoms = 0
            for g in groups:
                if g.indices:
                    natoms = max(natoms, max(g.indices) + 1)
            out_write(f"Deducing {natoms} atoms in the system from indices "
                      "in the index file\n")
    else:
        require_library_file(ctx, "residuetypes.dat")
        out_write("Analysing residue names:\n")
        counts = residue_type_counts(ctx, frame)
        for t, c in counts:
            out_write(f"There are: {c:5d} {t:>10s} residues\n")
        types_present = {t for t, _c in counts}
        if "Protein" in types_present:
            out_write("Analysing Protein...\n")
        if any(t not in ("Protein", "DNA", "RNA", "Water", "Ion")
               for t in types_present):
            out_write("Analysing residues not classified as Protein/DNA/RNA/Water "
                      "and splitting into groups...\n")
        groups = default_groups(ctx, frame)
        natoms = len(frame.atoms)
    if state.value("natoms"):
        # An explicit -natoms only takes effect when there is no structure
        # (and for -twin offsets); keep the frame count otherwise.
        if frame is None:
            natoms = int(state.value("natoms"))

    editor = Editor(ctx, frame, list(groups), natoms)
    _print_groups(editor.groups)
    while True:
        out_write("\n> ")
        try:
            sys.stdout.buffer.flush()
        except Exception:
            pass
        line = sys.stdin.readline()
        if line == "":
            raise GmxError(
                "Error reading user input\n", title="Fatal error:",
                source="src/gromacs/tools/make_ndx.cpp", line=1149,
                function=None, module_stage=True)
        if line.strip() == "q":
            break
        out_write("\n")
        editor.command(line)

    out_groups = list(editor.groups)
    if state.value("twin"):
        offset = int(state.value("natoms") or natoms)
        for g in list(out_groups):
            out_groups.append(
                Group(g.name + "_copy", [i + offset for i in g.indices]))
    outfile = state.file_value("o") or "index.ndx"
    ctx.write_output_file(outfile, format_ndx(out_groups))
    return ctx.finish_success(0)
