"""Reading trajectories in text formats, with GROMACS-style progress."""

from .main import err_write
from .structures import read_frames, file_extension


def trajectory_kind(filename):
    return file_extension(filename)


def read_trajectory(filename, *, progress=True, first_frame_info=False):
    frames = read_frames(filename)
    if progress and frames:
        ext = trajectory_kind(filename)
        first = frames[0]
        if ext == "gro":
            err_write(f"Reading frames from gro file '{first.title}', "
                      f"{len(first.atoms)} atoms.\n")
        elif ext in ("pdb", "brk", "ent", "esp"):
            err_write("Reading frames from pdb file")
        elif ext == "g96":
            pass
        else:
            err_write(f"Reading frames from {ext} file '{first.title}', "
                      f"{len(first.atoms)} atoms.\n")
        for i, fr in enumerate(frames):
            err_write(f"\rReading frame {i:7d} time {fr.time:8.3f}   ")
            if first_frame_info and i == 0:
                err_write(f"\n# Atoms  {len(fr.atoms)}\n")
                prec = {"gro": 0.001}.get(ext)
                if ext in ("pdb", "brk", "ent", "esp"):
                    prec = 0.0001
                if prec is not None:
                    err_write(f"Precision {prec:g} (nm)\n")
                if ext in ("pdb", "brk", "ent", "esp"):
                    err_write(f" '', {len(fr.atoms)} atoms\n")
        last = frames[-1]
        err_write(f"\rLast frame {len(frames) - 1:10d} time {last.time:8.3f}   \n")
    return frames
