"""Implementation of ``gmx check`` and ``gmx dump`` for text files."""

import math
import os

from .main import GmxError, out_write, err_write, wrap_line
from .numerics import fmt_g, f32
from .structures import (
    read_frames, file_extension, box_volume, read_lines,
)
from .trajectory import read_trajectory
from .groups import parse_ndx
from .library import require_library_file
from .masses import warn_guess_masses, load_atom_database, element_of


def _item_table(frames):
    def count(pred):
        return sum(1 for fr in frames if pred(fr))

    def timestep(values):
        vals = [v for v in values if v is not None]
        if len(vals) < 2:
            return ""
        dt = (vals[-1] - vals[0]) / (len(vals) - 1)
        return f"{dt:11.3f}" if dt else ""

    rows = [
        ("Step", count(lambda f: f.step != 0 or "step=" in f.title),
         timestep([f.time if ("step=" in f.title) else None for f in frames])),
        ("Time", count(lambda f: "t=" in f.title),
         timestep([f.time if ("t=" in f.title) else None for f in frames])),
        ("Lambda", 0, ""),
        ("Coords", len(frames), timestep([f.time for f in frames])
         if any("t=" in f.title for f in frames) else ""),
        ("Velocities", count(lambda f: any(a.vel is not None for a in f.atoms)),
         timestep([f.time if any(a.vel is not None for a in f.atoms) else None
                   for f in frames]) if any("t=" in f.title for f in frames) else ""),
        ("Forces", 0, ""),
        ("Box", count(lambda f: box_volume(f.box) != 0.0),
         timestep([f.time if box_volume(f.box) != 0.0 else None for f in frames])
         if any("t=" in f.title for f in frames) else ""),
    ]
    err_write("\n\nItem        #frames Timestep (ps)\n")
    for name, n, ts in rows:
        line = f"{name:<12s}{n:6d}"
        if ts:
            line += " " + ts.strip().rjust(11)
        err_write(line + "\n")


def _check_trajectory(ctx, state, filename):
    out_write(f"Checking file {filename}\n")
    frames = read_trajectory(filename, first_frame_info=True)
    _item_table(frames)
    return frames


def _compare_trajectories(ctx, state, fn1, fn2):
    err_write(f"Comparing trajectory files {fn1} and {fn2}\n")
    # The reference reads the two files in lockstep; for the text formats
    # supported here we read both fully and compare frame by frame, while
    # reproducing the progress output as closely as possible by reading
    # the first file and then the second.
    frames1 = read_trajectory(fn1)
    frames2 = read_trajectory(fn2)
    tol = float(state.value("tol"))
    abstol = float(state.value("abstol"))
    ok = True
    if len(frames1) != len(frames2):
        err_write(f"Warning: Number of frames differs: {len(frames1)} vs {len(frames2)}\n")
        ok = False
    for fi, (a, b) in enumerate(zip(frames1, frames2)):
        if len(a.atoms) != len(b.atoms):
            err_write(f"Frame {fi}: number of atoms differs\n")
            ok = False
            continue
        for i, (aa, bb) in enumerate(zip(a.atoms, b.atoms)):
            for d in range(3):
                x, y = aa.pos[d], bb.pos[d]
                denom = abs(x) + abs(y)
                rel = 2 * abs(x - y) / denom if denom else 0.0
                if rel > tol and abs(x - y) > abstol:
                    ok = False
    out_write("\n\nBoth files read correctly\n" if ok else "\n\nFiles differ\n")
    return 0


def _check_coordinate_file(ctx, state, filename):
    err_write(f"Checking coordinate file {filename}\n")
    ext = file_extension(filename)
    frames = read_frames(filename)
    if not frames:
        return 1
    frame = frames[0]
    atoms = frame.atoms
    masses = None
    if ext != "tpr":
        if ext in ("pdb", "brk", "ent", "esp"):
            require_library_file(ctx, "elements.dat")
        require_library_file(ctx, "residuetypes.dat")
        warn_guess_masses(ctx)
        require_library_file(ctx, "atommass.dat")
        table = load_atom_database(ctx, "atommass.dat")
        masses = []
        missing = False
        for a in atoms:
            key = (a.resname, a.atomname)
            if key in table:
                masses.append(table[key])
            elif ("*", a.atomname) in table:
                masses.append(table[("*", a.atomname)])
            else:
                masses.append(0.0)
                missing = True
                err_write(f"Can not find mass in database for atom {a.atomname} "
                          f"in residue {a.resnr} {a.resname}\n")
        if missing:
            raise GmxError(
                wrap_line("Masses were requested, but for some atom(s) masses "
                          "could not be found in the database. Use a tpr file "
                          "as input, if possible, or add these atoms to the "
                          "mass database.") + "\n",
                title="Fatal error:", source="src/gromacs/fileio/confio.cpp",
                line=525, function=None, module_stage=True)

    err_write(f"{len(atoms)} atoms in file\n")
    err_write("coordinates found\n")
    has_box = box_volume(frame.box) != 0.0
    err_write(f"{'box':<12s}{'found' if has_box else 'absent'}\n")
    has_vel = any(a.vel is not None for a in atoms)
    err_write(f"{'velocities':<12s}{'found' if has_vel else 'absent'}\n")

    if has_vel and masses is not None:
        ke = 0.5 * sum(masses[i] * sum(v * v for v in (atoms[i].vel or (0, 0, 0)))
                       for i in range(len(atoms)))
        err_write(f"\nKinetic energy: {fmt_g(f32(ke))} (kJ/mol)\n")
        boltzm = 0.00831446261815324
        t3 = 2 * ke / (3 * len(atoms) * boltzm) if atoms else 0.0
        t2 = 2 * ke / (2 * len(atoms) * boltzm) if atoms else 0.0
        err_write("Assuming the number of degrees of freedom to be Natoms * 3 or Natoms * 2,\n")
        err_write("the velocities correspond to a temperature of the system\n")
        err_write(f"of {fmt_g(f32(t3))} K or {fmt_g(f32(t2))} K respectively.\n")

    vdwfac = float(state.value("vdwfac"))
    bonlo = float(state.value("bonlo"))
    bonhi = float(state.value("bonhi"))
    err_write(f"\nChecking for atoms closer than {fmt_g(f32(vdwfac))} and not between "
              f"{fmt_g(f32(bonlo))} and {fmt_g(f32(bonhi))},\n")
    err_write("relative to sum of Van der Waals distance:\n")

    radii = [0.14] * len(atoms)
    if ext != "tpr":
        require_library_file(ctx, "vdwradii.dat")
        warn_guess_masses(ctx, force=True)
        rtable = load_atom_database(ctx, "vdwradii.dat")
        for i, a in enumerate(atoms):
            if (a.resname, a.atomname) in rtable:
                radii[i] = rtable[(a.resname, a.atomname)]
            elif ("*", a.atomname) in rtable:
                radii[i] = rtable[("*", a.atomname)]

    close = []
    box = frame.box
    for i in range(len(atoms)):
        for j in range(i + 1, len(atoms)):
            d = _pbc_distance(atoms[i].pos, atoms[j].pos, box)
            denom = radii[i] + radii[j]
            ratio = d / denom if denom else 0.0
            if ratio < vdwfac and not (bonlo <= ratio <= bonhi):
                close.append((i, j, d))
    if not close:
        err_write("\rno close atoms found\n")
    else:
        err_write("\ratom# name  residue r_vdw  atom# name  residue r_vdw  distance\n")
        for i, j, d in close:
            a, b = atoms[i], atoms[j]
            err_write(
                f"\r{i + 1:5d} {a.atomname:>4s}  {a.resname:<4s}{a.resnr:4d} "
                f"{radii[i]:.2f}   {j + 1:5d} {b.atomname:>4s}  {b.resname:<4s}"
                f"{b.resnr:4d} {radii[j]:.2f}   {d:.2f}  \n")
    err_write("\r      \n")

    outside = []
    if has_box:
        for i, a in enumerate(atoms):
            frac = _fractional(a.pos, box)
            if frac is not None and any(v < 0.0 or v >= 1.0 for v in frac):
                outside.append(i)
    if not outside:
        err_write("no atoms found outside box\n\n")
    else:
        lens = [math.sqrt(sum(x * x for x in row)) for row in box]
        err_write("Atoms outside box ( " +
                  " ".join(fmt_g(f32(x)) for x in lens) + " ):\n")
        err_write("(These may occur often and are normally not a problem)\n")
        err_write("atom# name  residue r_vdw  coordinate\n")
        for i in outside:
            a = atoms[i]
            coords = "".join(f"{fmt_g(f32(v)):>7s}" for v in a.pos)
            err_write(f"{i:5d} {a.atomname:>4s}  {a.resname:<4s}{a.resnr:4d} "
                      f"{radii[i]:.2f}   {coords}\n")
        err_write("\n")
    return 0


def _pbc_distance(p, q, box):
    # Minimum-image distance for diagonal boxes; general triclinic boxes
    # are handled through fractional coordinates when invertible.
    frac_p = _fractional(p, box)
    frac_q = _fractional(q, box)
    if frac_p is None:
        return math.sqrt(sum((p[d] - q[d]) ** 2 for d in range(3)))
    df = [frac_p[d] - frac_q[d] for d in range(3)]
    df = [v - round(v) for v in df]
    cart = [sum(df[k] * box[k][d] for k in range(3)) for d in range(3)]
    return math.sqrt(sum(x * x for x in cart))


def _fractional(pos, box):
    # Solve box^T?  Coordinates are row vectors: pos = frac . box
    import copy

    m = [[box[k][d] for k in range(3)] for d in range(3)]
    a = [row[:] + [pos[i]] for i, row in enumerate(m)]
    for col in range(3):
        piv = max(range(col, 3), key=lambda r: abs(a[r][col]))
        if abs(a[piv][col]) < 1e-20:
            return None
        a[col], a[piv] = a[piv], a[col]
        for r in range(col + 1, 3):
            factor = a[r][col] / a[col][col]
            for c in range(col, 4):
                a[r][c] -= factor * a[col][c]
    x = [0.0, 0.0, 0.0]
    for i in (2, 1, 0):
        x[i] = (a[i][3] - sum(a[i][j] * x[j] for j in range(i + 1, 3))) / a[i][i]
    return x


def tool_check(ctx, state):
    # Trajectory comparison / checking.
    if state.is_set("f") or state.is_set("f2"):
        f1 = state.file_value("f")
        f2 = state.file_value("f2")
        if state.is_set("f") and state.is_set("f2"):
            _compare_trajectories(ctx, state, f1, f2)
            return ctx.finish_success(0)
        if state.is_set("f"):
            _check_trajectory(ctx, state, f1)
            return ctx.finish_success(0)
    if state.is_set("c"):
        rc = _check_coordinate_file(ctx, state, state.file_value("c"))
        return ctx.finish_success(rc)
    if state.is_set("n"):
        fn = state.file_value("n")
        groups = parse_ndx(fn)
        out_write(f"Contents of index file {fn}\n")
        out_write("--------------------------------------------------\n")
        out_write("Nr.   Group               #Entries   First    Last\n")
        for i, g in enumerate(groups):
            first = g.indices[0] + 1 if g.indices else 0
            last = g.indices[-1] + 1 if g.indices else 0
            out_write(f"{i:4d}  {g.name:<20s} {len(g.indices):9d} "
                      f"{first:7d} {last:7d}\n")
        return ctx.finish_success(0)
    if state.is_set("s1") or state.is_set("s2") or state.is_set("e") or state.is_set("e2"):
        # Binary run-input / energy comparisons are not supported yet.
        raise GmxError(
            "Checking binary run input or energy files is not supported "
            "by this reimplementation.\n", title="Fatal error:",
            source="src/gromacs/tools/check.cpp", line=1, function=None)
    return ctx.finish_success(0)


def tool_dump(ctx, state):
    # Plain topology files are echoed (after preprocessing in the
    # reference); text trajectories are reported as unsupported.
    if state.is_set("p"):
        fn = state.file_value("p")
        for line in read_lines(fn):
            out_write(line + "\n")
        return ctx.finish_success(0)
    for name in ("s", "f", "e", "cp", "mtx"):
        if state.is_set(name):
            fn = state.file_value(name)
            ext = file_extension(fn)
            if ext in ("gro", "g96", "pdb", "brk", "ent", "esp"):
                err_write(f"File {fn} is of an unsupported type. Try using "
                          f"the command\n 'less {fn}'\n")
                return ctx.finish_success(0)
            # A file that is not a valid binary run-input/energy/trajectory
            # file fails in the XDR layer in the reference.
            try:
                with open(fn, "rb") as fh:
                    magic = fh.read(4)
            except OSError:
                magic = b""
            raise GmxError(
                "Failed to serialize string contents to XDR\n",
                title="System I/O error:",
                source="src/gromacs/fileio/xdr_serializer.cpp", line=350,
                function="virtual void gmx::XdrSerializer::doString(std::string*)",
                module_stage=True)
    return ctx.finish_success(0)
