    # supported here we read both fully and compare frame by frame, while
    # reproducing the progress output as closely as possible by reading
    # the first file and then the second.
    frames1 = read_trajectory(fn1)
    frames2 = read_trajectory(fn2)
    tol = float(state.value("tol"))
    abstol = float(state.value("abstol"))
    ok = True
    if len(frames1) != len(frames2):
