        f1 = state.file_value("f")
        f2 = state.file_value("f2")
        if state.is_set("f") and state.is_set("f2"):
            _compare_trajectories(ctx, state, f1, f2)
            return ctx.finish_success(0)
        if state.is_set("f"):
            _check_trajectory(ctx, state, f1)
            return ctx.finish_success(0)
    if state.is_set("c"):
        rc = _check_coordinate_file(ctx, state, state.file_value("c"))
        return ctx.finish_success(rc)
    if state.is_set("n"):
        fn = state.file_value("n")
        groups = parse_ndx(fn)
        out_write(f"Contents of index file {fn}\n")
        out_write("--------------------------------------------------\n")
        out_write("Nr.   Group               #Entries   First    Last\n")
        for i, g in enumerate(groups):
            first = g.indices[0] + 1 if g.indices else 0
            last = g.indices[-1] + 1 if g.indices else 0
            out_write(f"{i:4d}  {g.name:<20s} {len(g.indices):9d} "
                      f"{first:7d} {last:7d}\n")
        return ctx.finish_success(0)
    if state.is_set("s1") or state.is_set("s2") or state.is_set("e") or state.is_set("e2"):
        # Binary run-input / energy comparisons are not supported yet.
        raise GmxError(
            "Checking binary run input or energy files is not supported "
            "by this reimplementation.\n", title="Fatal error:",
            source="src/gromacs/tools/check.cpp", line=1, function=None)
    return ctx.finish_success(0)


def tool_dump(ctx, state):
    # Plain topology files are echoed (after preprocessing in the
    # reference); text trajectories are reported as unsupported.
    if state.is_set("p"):
        fn = state.file_value("p")
        for line in read_lines(fn):
            out_write(line + "\n")
        return ctx.finish_success(0)
    for name in ("s", "f", "e", "cp", "mtx"):
        if state.is_set(name):
            fn = state.file_value(name)
            ext = file_extension(fn)
            if ext in ("gro", "g96", "pdb", "brk", "ent", "esp"):
                err_write(f"File {fn} is of an unsupported type. Try using "
                          f"the command\n 'less {fn}'\n")
                return ctx.finish_success(0)
            # A file that is not a valid binary run-input/energy/trajectory
            # file fails in the XDR layer in the reference.
            try:
                with open(fn, "rb") as fh:
                    magic = fh.read(4)
            except OSError:
                magic = b""
            raise GmxError(
                "Failed to serialize string contents to XDR\n",
                title="System I/O error:",
                source="src/gromacs/fileio/xdr_serializer.cpp", line=350,
                function="virtual void gmx::XdrSerializer::doString(std::string*)",
                module_stage=True)
    return ctx.finish_success(0)
