        if state.is_set("f"):
            _check_trajectory(ctx, state, f1)
            return ctx.finish_success(0)
    if state.is_set("c"):
        rc = _check_coordinate_file(ctx, state, state.file_value("c"))
        return ctx.finish_success(rc)
    if state.is_set("n"):
        fn = state.file_value("n")
        groups = parse_ndx(fn)
        out_write(f"Contents of index file {fn}\n")
        out_write("--------------------------------------------------\n")
        out_write("Nr.   Group               #Entries   First    Last\n")
        for i, g in enumerate(groups):
