            "by this reimplementation.\n", title="Fatal error:",
            source="src/gromacs/tools/check.cpp", line=1, function=None)
    return ctx.finish_success(0)


def tool_dump(ctx, state):
    # Plain topology files are echoed (after preprocessing in the
    # reference); text trajectories are reported as unsupported.
    if state.is_set("p"):
        fn = state.file_value("p")
        for line in read_lines(fn):
            out_write(line + "\n")
        return ctx.finish_success(0)
    for name in ("s", "f", "e", "cp", "mtx"):
        if state.is_set(name):
            fn = state.file_value(name)
            ext = file_extension(fn)
            if ext in ("gro", "g96", "pdb", "brk", "ent", "esp"):
                err_write(f"File {fn} is of an unsupported type. Try using "
                          f"the command\n 'less {fn}'\n")
                return ctx.finish_success(0)
            # A file that is not a valid binary run-input/energy/trajectory
            # file fails in the XDR layer in the reference.
            try:
                with open(fn, "rb") as fh:
                    magic = fh.read(4)
            except OSError:
                magic = b""
            raise GmxError(
                "Failed to serialize string contents to XDR\n",
                title="System I/O error:",
                source="src/gromacs/fileio/xdr_serializer.cpp", line=350,
                function="virtual void gmx::XdrSerializer::doString(std::string*)",
                module_stage=True)
    return ctx.finish_success(0)
