{"command":"cat <<'PYEOF' > app/gmxclone/selections.py
"""Parser and evaluator for the GROMACS selection language.

Implementing the documented syntax from the bundled help topics
(``gmx help selections``): boolean combinations, keyword selections by
integer/numeric/string properties, comparisons and arithmetic,
``within``/``same``/``insolidangle``, centres (``com``/``cog``), position
types (``res_com`` etc.), variables, named selections, and the
``plus``/``merge``/``permute`` combinators.
"""

import math
import re

from .numerics import f32
from .structures import residue_instances


class SelectionSyntaxError(Exception):
    def __init__(self, token, special=None):
        self.token = token
        self.special = special


class SelectionEvalError(Exception):
    pass


# ---------------------------------------------------------------------------
# Tokeniser
# ---------------------------------------------------------------------------

_TOKEN_RE = re.compile(
    r'"(?:[^"\\]|\\.)*"|<=|>=|==|!=|[A-Za-z_][A-Za-z0-9_]*|'
    r'\d+(?:\.\d*)?(?:[eE][+-]?\d+)?|\.\d+(?:[eE][+-]?\d+)?|'
    r'[;,\(\)\[\]\{\}<>=?~+\-*/^&|!]'
)


class Token:
    __slots__ = ("text", "kind")

    def __init__(self, text):
        self.text = text
        if text.startswith('"'):
            self.kind = "string"
        elif re.fullmatch(r"\d+(?:\.\d*)?(?:[eE][+-]?\d+)?|\.\d+(?:[eE][+-]?\d+)?", text):
            self.kind = "number"
        elif re.fullmatch(r"[A-Za-z_][A-Za-z0-9_]*", text):
            self.kind = "ident"
        else:
            self.kind = "symbol"

    @property
    def string_value(self):
        body = self.text[1:-1]
        return body.replace('\\"', '"').replace("\\\\", "\\")

    def __repr__(self):
        return f"Tok({self.text!r})"


def tokenize(text):
    tokens = []
    pos = 0
    n = len(text)
    while pos < n:
        if text[pos] in " \t\r\n":
            pos += 1
            continue
        m = _TOKEN_RE.match(text, pos)
        if not m:
            raise SelectionSyntaxError(text[pos])
        tokens.append(Token(m.group(0)))
        pos = m.end()
    return tokens


# ---------------------------------------------------------------------------
# Keyword tables
# ---------------------------------------------------------------------------

INT_PROPS = {
    "atomnr": "atomnr", "resid": "resnr", "resnr": "resnr",
    "residue": "resindex", "resindex": "resindex",
    "mol": "molindex", "molecule": "molindex", "molindex": "molindex",
}
NUM_PROPS = {
    "beta": "betafactor", "betafactor": "betafactor", "charge": "charge",
    "mass": "mass", "occupancy": "occupancy", "x": "x", "y": "y", "z": "z",
}
STRING_PROPS = {
    "name": "atomname", "atomname": "atomname",
    "pdbname": "pdbatomname", "pdbatomname": "pdbatomname",
    "resname": "resname", "type": "atomtype", "atomtype": "atomtype",
    "chain": "chain", "altloc": "altloc", "insertcode": "insertcode",
}
POSTYPE_BASES = {"atom", "res_com", "res_cog", "mol_com", "mol_cog"}
POSTYPE_PREFIXES = ("whole_", "part_", "dyn_")
DISTANCE_WORDS = {"distance": "distance", "dist": "distance",
                  "mindistance": "mindistance", "mindist": "mindistance"}
COMPARISONS = ("<", "<=", ">", ">=", "==", "!=")


def split_postype(word):
    for prefix in POSTYPE_PREFIXES:
        if word.startswith(prefix) and word[len(prefix):] in POSTYPE_BASES:
            return prefix[:-1], word[len(prefix):]
    if word in POSTYPE_BASES:
        return None, word
    return None


def is_postype(word):
    return split_postype(word) is not None


# ---------------------------------------------------------------------------
# Parser
# ---------------------------------------------------------------------------

class Parser:
    def __init__(self, tokens, variables=None):
        self.toks = tokens
        self.pos = 0
        self.variables = variables if variables is not None else {}

    def peek(self, ahead=0):
        i = self.pos + ahead
        return self.toks[i] if i < len(self.toks) else None

    def next(self):
        tok = self.peek()
        if tok is None:
            raise SelectionSyntaxError(self.toks[-1].text if self.toks else "")
        self.pos += 1
        return tok

    def expect(self, text):
        tok = self.peek()
        if tok is None or tok.text != text:
            raise SelectionSyntaxError(tok.text if tok else (self.toks[-1].text if self.toks else ""))
        self.pos += 1
        return tok

    def at_end(self):
        return self.pos >= len(self.toks)

    # ----- position expressions -----------------------------------------
    def parse_pos_expr(self):
        node = self.parse_pos_term()
        while True:
            tok = self.peek()
            if tok is not None and tok.kind == "ident" and tok.text in ("plus", "merge"):
                op = self.next().text
                stride = None
                rhs = self.parse_pos_term()
                if op == "merge":
                    t2 = self.peek()
                    if t2 is not None and t2.kind == "ident" and t2.text == "stride":
                        self.next()
                        num = self.next()
                        if num.kind != "number":
                            raise SelectionSyntaxError(num.text)
                        stride = int(float(num.text))
                node = (op, node, rhs, stride)
            else:
                break
        tok = self.peek()
        if tok is not None and tok.kind == "ident" and tok.text == "permute":
            self.next()
            perm = []
            while True:
                t = self.peek()
                if t is not None and t.kind == "number":
                    perm.append(int(float(t.text)))
                    self.pos += 1
                else:
                    break
            if not perm:
                raise SelectionSyntaxError("permute")
            node = ("permute", node, perm)
        return node

    def parse_pos_term(self):
        tok = self.peek()
        if tok is None:
            raise SelectionSyntaxError(self.toks[-1].text if self.toks else "")
        if tok.text == "[":
            self.next()
            coords = []
            for i in range(3):
                sign = 1.0
                if self.peek() is not None and self.peek().text == "-":
                    self.next(); sign = -1.0
                num = self.next()
                if num.kind != "number":
                    raise SelectionSyntaxError(num.text)
                coords.append(sign * float(num.text))
                if i < 2:
                    self.expect(",")
            self.expect("]")
            return ("const", tuple(coords))
        if tok.kind == "ident" and tok.text in ("com", "cog"):
            kind = self.next().text
            of = self.next()
            if of.text != "of":
                raise SelectionSyntaxError(of.text)
            sub = self.parse_atom_expr()
            pbc = False
            t = self.peek()
            if t is not None and t.kind == "ident" and t.text == "pbc":
                self.next(); pbc = True
            return ("center", kind, sub, pbc)
        if tok.kind == "ident" and is_postype(tok.text):
            nxt = self.peek(1)
            if nxt is not None and nxt.text == "of":
                postype = self.next().text
                self.next()
                sub = self.parse_atom_expr()
                return ("grouppos", postype, sub)
        sub = self.parse_atom_expr()
        return ("atompos", sub)

    # ----- atom expressions ---------------------------------------------
    def parse_atom_expr(self):
        return self._parse_or()

    def _parse_or(self):
        node = self._parse_and()
        while True:
            tok = self.peek()
            if tok is not None and tok.kind == "ident" and tok.text == "or":
                self.next()
                rhs = self._parse_and()
                node = ("or", node, rhs)
            else:
                return node

    def _parse_and(self):
        node = self._parse_unary()
        while True:
            tok = self.peek()
            if tok is not None and tok.kind == "ident" and tok.text == "and":
                self.next()
                rhs = self._parse_unary()
                node = ("and", node, rhs)
            else:
                return node

    def _parse_unary(self):
        tok = self.peek()
        if tok is not None and tok.kind == "ident" and tok.text == "not":
            self.next()
            return ("not", self._parse_unary())
        return self._parse_atom_primary()

    def _parse_atom_primary(self):
        tok = self.peek()
        if tok is None:
            raise SelectionSyntaxError(self.toks[-1].text if self.toks else "")
        if tok.text == "(":
            self.next()
            node = self.parse_atom_expr()
            if self.peek() is None or self.peek().text != ")":
                raise SelectionSyntaxError(")")
            self.next()
            return node
        if tok.kind == "string":
            self.next()
            return ("group_name", tok.string_value)
        if tok.kind == "number":
            nxt = self.peek(1)
            if nxt is not None and (nxt.text in COMPARISONS or nxt.text in ("+", "-", "*", "/", "^")):
                return self._parse_numeric_comparison()
            self.next()
            return ("group_index", int(float(tok.text)))
        if tok.kind != "ident":
            # Numeric expression starting with - or similar.
            return self._parse_numeric_comparison()
        word = tok.text
        if word == "all":
            self.next(); return ("all",)
        if word == "none":
            self.next(); return ("none",)
        if word == "group":
            self.next()
            arg = self.next()
            if arg.kind == "number":
                return ("group_index", int(float(arg.text)))
            if arg.kind == "string":
                return ("group_name", arg.string_value)
            if arg.kind == "ident":
                return ("group_name", arg.text)
            raise SelectionSyntaxError(arg.text)
        if word == "same":
            self.next()
            keytok = self.next()
            if keytok.kind != "ident":
                raise SelectionSyntaxError(keytok.text)
            key = keytok.text
            astok = self.next()
            if astok.text != "as":
                raise SelectionSyntaxError(astok.text)
            sub = self.parse_atom_expr()
            return ("same", key, sub)
        if word == "within":
            self.next()
            disttok = self.next()
            sign = 1.0
            if disttok.text == "-":
                sign = -1.0
                disttok = self.next()
            if disttok.kind != "number":
                raise SelectionSyntaxError(disttok.text)
            dist = sign * float(disttok.text)
            of = self.peek()
            if of is None:
                raise SelectionSyntaxError(
                    "of", special="within_of")
            if of.text != "of":
                raise SelectionSyntaxError(of.text)
            self.next()
            if self.at_end() or (self.peek() is not None and self.peek().text in (";", ")")):
                raise SelectionSyntaxError("of", special="within_of")
            sub = self.parse_pos_term()
            return ("within", dist, sub)
        if word == "insolidangle":
            self.next()
            ctok = self.next()
            if ctok.text != "center":
                raise SelectionSyntaxError(ctok.text)
            center = self.parse_pos_term()
            stok = self.next()
            if stok.text != "span":
                raise SelectionSyntaxError(stok.text)
            span = self.parse_pos_term()
            cutoff = 5.0
            t = self.peek()
            if t is not None and t.kind == "ident" and t.text == "cutoff":
                self.next()
                num = self.next()
                if num.kind != "number":
                    raise SelectionSyntaxError(num.text)
                cutoff = float(num.text)
            return ("insolidangle", center, span, cutoff)
        if word in STRING_PROPS:
            return self._parse_string_prop()
        if word in INT_PROPS or word in NUM_PROPS:
            return self._parse_numeric_prop_or_comparison()
        if word in DISTANCE_WORDS:
            return self._parse_numeric_comparison()
        if is_postype(word):
            return self._parse_numeric_comparison()
        if word in self.variables:
            varnode = self.variables[word]
            if varnode[0] == "numvar":
                return self._parse_numeric_comparison()
            self.next()
            return ("var", word)
        # A bare identifier refers to an index group.
        self.next()
        return ("group_name", word)

    def _parse_string_prop(self):
        prop_tok = self.next()
        prop = STRING_PROPS[prop_tok.text]
        tok = self.peek()
        if tok is not None and tok.text in ("=", "?", "~"):
            op = self.next().text
            val = self.next()
            if val.kind == "string":
                pattern = val.string_value
            elif val.kind in ("ident", "number"):
                pattern = val.text
            else:
                raise SelectionSyntaxError(val.text)
            return ("string_prop", prop, [pattern], op)
        if tok is not None and tok.text in ("==", "!=", "<", ">", "<=", ">="):
            raise SelectionSyntaxError(tok.text)
        patterns = []
        while True:
            t = self.peek()
            if t is None or t.text in (";", ")", "&", "|"):
                break
            if t.kind == "ident" and t.text in ("and", "or", "plus", "merge", "permute"):
                break
            if t.kind == "string":
                patterns.append(t.string_value); self.pos += 1
            elif t.kind in ("ident", "number"):
                patterns.append(t.text); self.pos += 1
            else:
                break
        if not patterns:
            raise SelectionSyntaxError(prop_tok.text)
        return ("string_prop", prop, patterns, None)

    def _scan_direct_list(self, start):
        """Try to scan a value/range list starting at token index start.

        Returns (ranges, end_index) or None.
        """
        ranges = []
        i = start
        n = len(self.toks)
        while i < n:
            tok = self.toks[i]
            if tok.kind != "number":
                break
            lo = float(tok.text); i += 1
            hi = lo
            if i < n and self.toks[i].kind == "ident" and self.toks[i].text == "to":
                if i + 1 >= n or self.toks[i + 1].kind not in ("number",) and self.toks[i + 1].text != "-":
                    return None
                i += 1
                sign = 1.0
                if self.toks[i].text == "-":
                    sign = -1.0; i += 1
                if i >= n or self.toks[i].kind != "number":
                    return None
                hi = sign * float(self.toks[i].text); i += 1
            elif (i + 1 < n and self.toks[i].text == "-"
                  and self.toks[i + 1].kind == "number"):
                hi = float(self.toks[i + 1].text); i += 2
            ranges.append((lo, hi))
        if not ranges:
            return None
        return ranges, i

    def _parse_numeric_prop_or_comparison(self):
        tok = self.peek()
        word = tok.text
        nxt = self.peek(1)
        # Braced list, e.g. charge {-1 to -0.7}
        if nxt is not None and nxt.text == "{":
            self.next(); self.next()
            scanned = self._scan_braced_list()
            self.expect("}")
            prop = INT_PROPS.get(word) or NUM_PROPS.get(word)
            return ("num_list", prop, None, scanned)
        if nxt is not None and nxt.kind == "number":
            scanned = self._scan_direct_list(self.pos + 1)
            if scanned is not None:
                ranges, end = scanned
                after = self.toks[end] if end < len(self.toks) else None
                if after is None or after.text in (";", ")", "&", "|") or (
                        after.kind == "ident" and after.text in
                        ("and", "or", "plus", "merge", "permute", "pbc")):
                    self.pos = end
                    prop = INT_PROPS.get(word) or NUM_PROPS.get(word)
                    return ("num_list", prop, None, ranges)
        return self._parse_numeric_comparison()

    def _scan_braced_list(self):
        ranges = []
        while True:
            sign = 1.0
            if self.peek() is not None and self.peek().text == "-":
                self.next(); sign = -1.0
            num = self.next()
            if num.kind != "number":
                raise SelectionSyntaxError(num.text)
            lo = sign * float(num.text); hi = lo
            t = self.peek()
            if t is not None and t.kind == "ident" and t.text == "to":
                self.next()
                sign = 1.0
                if self.peek() is not None and self.peek().text == "-":
                    self.next(); sign = -1.0
                num = self.next()
                if num.kind != "number":
                    raise SelectionSyntaxError(num.text)
                hi = sign * float(num.text)
            ranges.append((lo, hi))
            if self.peek() is not None and self.peek().text == "}":
                break
        return ranges

    def _parse_numeric_comparison(self):
        left = self.parse_numeric_expr()
        tok = self.peek()
        if tok is None or tok.text not in COMPARISONS:
            raise SelectionSyntaxError(tok.text if tok else self.toks[-1].text)
        op = self.next().text
        right = self.parse_numeric_expr()
        return ("compare", left, op, right)

    # ----- numeric expressions -------------------------------------------
    def parse_numeric_expr(self):
        return self._parse_add()

    def _parse_add(self):
        node = self._parse_mul()
        while True:
            tok = self.peek()
            if tok is not None and tok.text in ("+", "-"):
                op = self.next().text
                rhs = self._parse_mul()
                node = ("arith", op, node, rhs)
            else:
                return node

    def _parse_mul(self):
        node = self._parse_pow()
        while True:
            tok = self.peek()
            if tok is not None and tok.text in ("*", "/"):
                op = self.next().text
                rhs = self._parse_pow()
                node = ("arith", op, node, rhs)
            else:
                return node

    def _parse_pow(self):
        node = self._parse_numeric_unary()
        tok = self.peek()
        if tok is not None and tok.text == "^":
            self.next()
            rhs = self._parse_pow()
            node = ("arith", "^", node, rhs)
        return node

    def _parse_numeric_unary(self):
        tok = self.peek()
        if tok is not None and tok.text == "-":
            self.next()
            return ("neg", self._parse_numeric_unary())
        if tok is not None and tok.text == "+":
            self.next()
            return self._parse_numeric_unary()
        return self._parse_numeric_primary()

    def _parse_numeric_primary(self):
        tok = self.peek()
        if tok is None:
            raise SelectionSyntaxError(self.toks[-1].text if self.toks else "")
        if tok.kind == "number":
            self.next()
            return ("scalar", float(tok.text))
        if tok.text == "(":
            self.next()
            node = self.parse_numeric_expr()
            self.expect(")")
            return node
        if tok.kind != "ident":
            raise SelectionSyntaxError(tok.text)
        word = tok.text
        # Qualified by a position type, e.g. res_com x, res_com distance...
        if is_postype(word):
            self.next()
            inner = self._parse_numeric_primary()
            return ("qualified", word, inner)
        if word in DISTANCE_WORDS:
            self.next()
            ftok = self.next()
            if ftok.text != "from":
                raise SelectionSyntaxError(ftok.text)
            sub = self.parse_pos_term()
            cutoff = None
            t = self.peek()
            if t is not None and t.kind == "ident" and t.text == "cutoff":
                self.next()
                num = self.next()
                if num.kind != "number":
                    raise SelectionSyntaxError(num.text)
                cutoff = float(num.text)
            return ("distance", DISTANCE_WORDS[word], sub, cutoff)
        if word in ("x", "y", "z"):
            nxt = self.peek(1)
            if nxt is not None and nxt.text == "of":
                self.next(); self.next()
                sub = self.parse_pos_term()
                return ("coord_of", word, sub)
            self.next()
            return ("prop", NUM_PROPS[word])
        if word in INT_PROPS:
            self.next()
            return ("prop", INT_PROPS[word])
        if word in NUM_PROPS:
            self.next()
            return ("prop", NUM_PROPS[word])
        if word in self.variables:
            self.next()
            return ("var", word)
        raise SelectionSyntaxError(word)


class CompiledSelection:
    __slots__ = ("name", "node", "text")

    def __init__(self, name, node, text):
        self.name = name
        self.node = node
        self.text = text


def parse_selection_collection(text, variables=None):
    """Parse a semicolon-separated selection collection.

    Returns a list of CompiledSelection.  ``variables`` is a dict shared
    across calls (assignment statements update it and produce no output).
    """
    if variables is None:
        variables = {}
    tokens = tokenize(text)
    # Split on top-level semicolons.
    chunks = []
    cur = []
    for tok in tokens:
        if tok.text == ";":
            chunks.append(cur); cur = []
        else:
            cur.append(tok)
    chunks.append(cur)
    result = []
    for chunk in chunks:
        if not chunk:
            continue
        # Reconstruct the item text for default naming (single spaces,
        # as in the original token stream, is close enough for legends;
        # the caller normally passes the original text for one selection).
        parser = Parser(chunk, variables)
        # Variable assignment?
        if (len(chunk) >= 2 and chunk[0].kind == "ident"
                and chunk[1].text == "="):
            varname = chunk[0].text
            parser.pos = 2
            # Determine the stored node kind: numeric if it parses as a
            # numeric expression with a comparison-free tail, else a
            # position expression.  Position parsing subsumes the common
            # cases (com/distance assignments are handled below).
            start_tok = chunk[2] if len(chunk) > 2 else None
            if start_tok is not None and start_tok.kind == "ident" and (
                    start_tok.text in DISTANCE_WORDS or is_postype(start_tok.text)):
                node = parser.parse_numeric_expr()
                variables[varname] = ("numvar", node)
            else:
                node = parser.parse_pos_expr()
                variables[varname] = node
            if not parser.at_end():
                raise SelectionSyntaxError(parser.peek().text)
            continue
        # Optional name string.
        sel_name = None
        if chunk[0].kind == "string" and len(chunk) > 1:
            sel_name = chunk[0].string_value
            parser.pos = 1
        node = parser.parse_pos_expr()
        if not parser.at_end():
            raise SelectionSyntaxError(parser.peek().text)
        if sel_name is None:
            sel_name = text.strip() if len(chunks) == 1 else " ".join(
                t.text for t in chunk)
        result.append(CompiledSelection(sel_name, node, text))
    return result


def validate_selection(text):
    """Return error details for the command-line parser, or None."""
    try:
        parse_selection_collection(text, {})
    except SelectionSyntaxError as e:
        if e.special == "within_of":
            return [
                (4, f"Invalid selection '{text}'"),
                (6, f"While parsing '{text}'"),
                (8, "In 'of'"),
                (10, "'of' should be followed by a value/expression"),
            ]
        return [
            (4, f"Invalid selection '{text}'"),
            (6, f"Near '{e.token}'"),
            (8, "syntax error"),
        ]
    return None


# ---------------------------------------------------------------------------
# Evaluation
# ---------------------------------------------------------------------------

class SelPosition:
    __slots__ = ("pos", "atoms")

    def __init__(self, pos, atoms):
        self.pos = tuple(pos)
        self.atoms = tuple(atoms)


class SelectionEngine:
    def __init__(self, topology, groups, masses, *, seltype="atom",
                 selrpos="atom", variables=None, pbc=True):
        self.topology = topology
        self.groups = groups or []
        self.masses = masses or [0.0] * len(topology.atoms)
        self.seltype = seltype or "atom"
        self.selrpos = selrpos or "atom"
        self.variables = variables if variables is not None else {}
        self.pbc = pbc
        self.natoms = len(topology.atoms)
        self.residues = residue_instances(topology)
        self.atom_resindex = [0] * self.natoms
        for ri, (_key, ats) in enumerate(self.residues):
            for a in ats:
                self.atom_resindex[a] = ri
        self._part_cache = {}

    # ----- utilities -------------------------------------------------------
    def _frame_pos(self, frame, i):
        if i < len(frame.atoms):
            return frame.atoms[i].pos
        return self.topology.atoms[i].pos

    def _distance(self, p, q, box):
        d = [p[k] - q[k] for k in range(3)]
        if self.pbc and box is not None:
            # Orthorhombic/triclinic minimum image via fractional coords
            # when the box is diagonal; fall back to direct otherwise.
            diag = [box[k][k] for k in range(3)]
            if all(abs(box[i][j]) < 1e-12 for i in range(3) for j in range(3) if i != j):
                for k in range(3):
                    if diag[k]:
                        d[k] -= diag[k] * round(d[k] / diag[k])
        return math.sqrt(sum(x * x for x in d))

    def _center_of(self, frame, indices, kind):
        if not indices:
            return None
        if kind == "com":
            weights = [self.masses[i] if i < len(self.masses) else 0.0
                       for i in indices]
            total = sum(weights)
            if total == 0:
                weights = [1.0] * len(indices); total = float(len(indices))
        else:
            weights = [1.0] * len(indices); total = float(len(indices))
        return tuple(
            sum(weights[k] * self._frame_pos(frame, indices[k])[d]
                for k in range(len(indices))) / total
            for d in range(3))

    def _grouping(self, base):
        """Atom groups for res_*/mol_* position types."""
        if base.startswith("res_"):
            return [list(ats) for (_k, ats) in self.residues]
        return [list(range(self.natoms))] if self.natoms else []

    def _positions_for_atoms(self, frame, indices, postype_word):
        parsed = split_postype(postype_word)
        if parsed is None:
            prefix, base = None, "atom"
        else:
            prefix, base = parsed
        if base == "atom":
            return [SelPosition(self._frame_pos(frame, i), [i]) for i in indices]
        kind = "com" if base.endswith("_com") else "cog"
        grouping = self._grouping(base)
        sel_set = set(indices)
        out = []
        cache_key = (postype_word, tuple(sorted(sel_set))) if prefix == "part" else None
        for grp in grouping:
            inter = [i for i in grp if i in sel_set]
            if not inter:
                continue
            if prefix == "whole":
                use = grp
            elif prefix == "dyn":
                use = inter
            else:  # part (default): atoms selected at first evaluation
                key = (postype_word, grp[0])
                if key not in self._part_cache:
                    self._part_cache[key] = list(inter)
                use = self._part_cache[key]
            c = self._center_of(frame, use, kind)
            if c is not None:
                out.append(SelPosition(c, use))
        return out

    def _reference_positions(self, frame, postype_word):
        """A reference position for every atom under a position type."""
        parsed = split_postype(postype_word or "atom")
        _prefix, base = parsed if parsed else (None, "atom")
        if base == "atom":
            return [self._frame_pos(frame, i) for i in range(self.natoms)]
        kind = "com" if base.endswith("_com") else "cog"
        result = [None] * self.natoms
        for grp in self._grouping(base):
            c = self._center_of(frame, grp, kind)
            for i in grp:
                result[i] = c
        return result

    def _find_group(self, name):
        for mode in ("exact", "prefix", "substring"):
            found = []
            for g in self.groups:
                if mode == "exact" and g.name == name:
                    found.append(g)
                elif mode == "prefix" and g.name.startswith(name):
                    found.append(g)
                elif mode == "substring" and name in g.name:
                    found.append(g)
            if len(found) == 1:
                return found[0]
            if len(found) > 1:
                raise SelectionEvalError(f"Multiple index groups match '{name}'")
        raise SelectionEvalError(f"No index group found matching '{name}'")

    # ----- atom evaluation ---------------------------------------------------
    def evaluate_atoms(self, node, frame):
        kind = node[0]
        if kind == "atompos":
            return self.evaluate_atoms(node[1], frame)
        if kind == "all":
            return list(range(self.natoms))
        if kind == "none":
            return []
        if kind == "group_index":
            k = node[1]
            if not (0 <= k < len(self.groups)):
                raise SelectionEvalError(f"Index group {k} is out of range")
            return list(self.groups[k].indices)
        if kind == "group_name":
            return list(self._find_group(node[1]).indices)
        if kind == "var":
            return self.evaluate_atoms(self.variables[node[1]], frame)
        if kind == "not":
            sub = set(self.evaluate_atoms(node[1], frame))
            return [i for i in range(self.natoms) if i not in sub]
        if kind == "and":
            return sorted(set(self.evaluate_atoms(node[1], frame))
                          & set(self.evaluate_atoms(node[2], frame)))
        if kind == "or":
            return sorted(set(self.evaluate_atoms(node[1], frame))
                          | set(self.evaluate_atoms(node[2], frame)))
        if kind == "string_prop":
            _k, prop, patterns, op = node
            out = []
            for i, a in enumerate(self.topology.atoms):
                value = self._string_property(a, prop)
                if any(self._match_string(value, p, op) for p in patterns):
                    out.append(i)
            return out
        if kind == "num_list":
            _k, prop, qual, ranges = node
            vals = self._numeric_property(frame, prop, qual)
            return [i for i in range(self.natoms)
                    if any(lo <= vals[i] <= hi for lo, hi in ranges)]
        if kind == "compare":
            _k, left, op, right = node
            lv = self._eval_numeric(left, frame)
            rv = self._eval_numeric(right, frame)
            out = []
            for i in range(self.natoms):
                x = lv[i] if isinstance(lv, list) else lv
                y = rv[i] if isinstance(rv, list) else rv
                if _compare(x, op, y):
                    out.append(i)
            return out
        if kind == "same":
            _k, key, sub = node
            sub_atoms = self.evaluate_atoms(sub, frame)
            keys = {self._same_key(a_idx, key) for a_idx in sub_atoms}
            return [i for i in range(self.natoms)
                    if self._same_key(i, key) in keys]
        if kind == "within":
            _k, dist, sub = node
            positions = self.evaluate_positions_node(sub, frame)
            refs = self._reference_positions(frame, self.selrpos)
            box = frame.box
            return [i for i in range(self.natoms)
                    if positions and min(self._distance(refs[i], p.pos, box)
                                         for p in positions) <= dist]
        if kind == "insolidangle":
            _k, center_node, span_node, cutoff = node
            centers = self.evaluate_positions_node(center_node, frame)
            spans = self.evaluate_positions_node(span_node, frame)
            if not centers or not spans:
                return []
            center = centers[0].pos
            refs = self._reference_positions(frame, self.selrpos)
            limit = math.cos(math.radians(cutoff))
            out = []
            span_dirs = []
            for p in spans:
                v = [p.pos[d] - center[d] for d in range(3)]
                n = math.sqrt(sum(x * x for x in v))
                if n:
                    span_dirs.append([x / n for x in v])
            for i in range(self.natoms):
                v = [refs[i][d] - center[d] for d in range(3)]
                n = math.sqrt(sum(x * x for x in v))
                if not n:
                    continue
                v = [x / n for x in v]
                if any(sum(v[d] * sd[d] for d in range(3)) >= limit
                       for sd in span_dirs):
                    out.append(i)
            return out
        raise SelectionEvalError(f"Cannot evaluate '{kind}' as an atom selection")

    def _same_key(self, i, key):
        a = self.topology.atoms[i]
        kl = key.lower()
        if kl in ("residue", "resindex"):
            return self.atom_resindex[i]
        if kl in ("resid", "resnr"):
            return a.resnr
        if kl == "resname":
            return a.resname
        if kl in ("mol", "molecule", "molindex"):
            return 0
        if kl == "chain":
            return a.chain
        if kl in ("name", "atomname"):
            return a.atomname
        if kl in ("type", "atomtype"):
            return ""
        if kl == "atomnr":
            return i + 1
        return self._string_property(a, kl)

    def _string_property(self, atom, prop):
        if prop in ("atomname", "pdbatomname"):
            return atom.atomname
        if prop == "resname":
            return atom.resname
        if prop == "chain":
            return atom.chain
        return ""

    def _match_string(self, value, pattern, op):
        if op == "=":
            return value == pattern
        if op == "?":
            mode = "glob"
        elif op == "~":
            mode = "regex"
        else:
            mode = ("regex" if re.search(r"[^A-Za-z0-9*?]", pattern)
                    else "glob")
        if mode == "glob":
            regex = ""
            for ch in pattern:
                if ch == "?":
                    regex += "."
                elif ch == "*":
                    regex += ".*"
                else:
                    regex += re.escape(ch)
            return re.fullmatch(regex, value) is not None
        try:
            return re.fullmatch(pattern, value) is not None
        except re.error:
            return False

    # ----- numeric evaluation --------------------------------------------------
    def _numeric_property(self, frame, prop, qualifier=None):
        atoms = self.topology.atoms
        if prop == "atomnr":
            return [float(i + 1) for i in range(self.natoms)]
        if prop == "resnr":
            return [float(a.resnr) for a in atoms]
        if prop == "resindex":
            return [float(self.atom_resindex[i] + 1) for i in range(self.natoms)]
        if prop == "molindex":
            return [1.0] * self.natoms
        if prop == "mass":
            return [float(self.masses[i]) if i < len(self.masses) else 0.0
                    for i in range(self.natoms)]
        if prop == "charge":
            return [0.0] * self.natoms
        if prop == "betafactor":
            return [float(a.bfactor) for a in atoms]
        if prop == "occupancy":
            return [float(a.occupancy) for a in atoms]
        if prop in ("x", "y", "z"):
            d = {"x": 0, "y": 1, "z": 2}[prop]
            refs = self._reference_positions(frame, qualifier or self.selrpos)
            return [float(refs[i][d]) for i in range(self.natoms)]
        return [0.0] * self.natoms

    def _eval_numeric(self, node, frame):
        kind = node[0]
        if kind == "scalar":
            return float(node[1])
        if kind == "prop":
            return self._numeric_property(frame, node[1])
        if kind == "qualified":
            _k, postype, inner = node
            if inner[0] == "prop":
                return self._numeric_property(frame, inner[1], qualifier=postype)
            if inner[0] == "distance":
                return self._eval_distance(frame, inner, qualifier=postype)
            # Fall back to unqualified evaluation.
            return self._eval_numeric(inner, frame)
        if kind == "distance":
            return self._eval_distance(frame, node, qualifier=None)
        if kind == "coord_of":
            _k, axis, sub = node
            positions = self.evaluate_positions_node(sub, frame)
            d = {"x": 0, "y": 1, "z": 2}[axis]
            vals = [p.pos[d] for p in positions]
            if len(vals) == 1:
                return float(vals[0])
            # Pad/truncate to per-atom list in the unlikely general case.
            return [float(vals[i]) if i < len(vals) else 0.0
                    for i in range(self.natoms)]
        if kind == "var":
            stored = self.variables[node[1]]
            if stored[0] == "numvar":
                return self._eval_numeric(stored[1], frame)
            raise SelectionEvalError("Variable does not hold a numeric expression")
        if kind == "neg":
            v = self._eval_numeric(node[1], frame)
            return [-x for x in v] if isinstance(v, list) else -v
        if kind == "arith":
            _k, op, lnode, rnode = node
            lv = self._eval_numeric(lnode, frame)
            rv = self._eval_numeric(rnode, frame)

            def apply(x, y):
                if op == "+":
                    return x + y
                if op == "-":
                    return x - y
                if op == "*":
                    return x * y
                if op == "/":
                    return x / y if y != 0 else math.copysign(math.inf, x)
                if op == "^":
                    try:
                        return math.pow(x, y)
                    except (ValueError, OverflowError):
                        return math.nan
                return 0.0

            if isinstance(lv, list) or isinstance(rv, list):
                return [apply(lv[i] if isinstance(lv, list) else lv,
                              rv[i] if isinstance(rv, list) else rv)
                        for i in range(self.natoms)]
            return apply(lv, rv)
        raise SelectionEvalError(f"Cannot evaluate '{kind}' numerically")

    def _eval_distance(self, frame, node, qualifier=None):
        _k, mode, sub, cutoff = node
        positions = self.evaluate_positions_node(sub, frame)
        refs = self._reference_positions(frame, qualifier or self.selrpos)
        box = frame.box
        out = []
        for i in range(self.natoms):
            if not positions:
                out.append(math.inf)
                continue
            if mode == "distance":
                d = self._distance(refs[i], positions[0].pos, box)
            else:
                d = min(self._distance(refs[i], p.pos, box) for p in positions)
            if cutoff is not None and d > cutoff:
                d = cutoff
            out.append(float(d))
        return out

    # ----- position evaluation ---------------------------------------------------
    def evaluate_positions_node(self, node, frame):
        kind = node[0]
        if kind == "const":
            return [SelPosition(node[1], [])]
        if kind == "atompos":
            atoms = self.evaluate_atoms(node[1], frame)
            return self._positions_for_atoms(frame, atoms, self.seltype)
        if kind == "grouppos":
            atoms = self.evaluate_atoms(node[2], frame)
            return self._positions_for_atoms(frame, atoms, node[1])
        if kind == "center":
            _k, ckind, sub, _pbc = node
            atoms = self.evaluate_atoms(sub, frame)
            c = self._center_of(frame, atoms, ckind)
            return [SelPosition(c, atoms)] if c is not None else []
        if kind == "var":
            return self.evaluate_positions_node(self.variables[node[1]], frame)
        if kind == "plus":
            _k, a, b, _stride = node
            return (self.evaluate_positions_node(a, frame)
                    + self.evaluate_positions_node(b, frame))
        if kind == "merge":
            _k, a, b, stride = node
            left = self.evaluate_positions_node(a, frame)
            right = self.evaluate_positions_node(b, frame)
            if stride is None:
                stride = (len(left) // len(right)) if right and len(left) % max(len(right), 1) == 0 and len(left) > len(right) else 1
            out = []
            # Interleave blocks of `stride` positions from the left with
            # single positions from the right (A1 B1 A2 B2 ... for
            # stride 1 with equal sizes).
            li = ri = 0
            while li < len(left) or ri < len(right):
                for _ in range(stride):
                    if li < len(left):
                        out.append(left[li]); li += 1
                if ri < len(right):
                    out.append(right[ri]); ri += 1
                if stride == 0:
                    break
            return out
        if kind == "permute":
            _k, sub, perm = node
            positions = self.evaluate_positions_node(sub, frame)
            n = len(perm)
            if n == 0 or len(positions) % n != 0:
                raise SelectionEvalError(
                    "Permutation size does not divide the selection size")
            out = []
            for base in range(0, len(positions), n):
                block = positions[base:base + n]
                newblock = [None] * n
                for i, p in enumerate(perm):
                    if not (1 <= p <= n):
                        raise SelectionEvalError("Invalid permutation index")
                    newblock[p - 1] = block[i]
                out.extend(newblock)
            return out
        # Any atom expression used directly as a position expression.
        atoms = self.evaluate_atoms(node, frame)
        return self._positions_for_atoms(frame, atoms, self.seltype)

    def evaluate(self, compiled, frame):
        return self.evaluate_positions_node(compiled.node, frame)


def _compare(x, op, y):
    if op == "<":
        return x < y
    if op == "<=":
        return x <= y
    if op == ">":
        return x > y
    if op == ">=":
        return x >= y
    if op == "==":
        return x == y
    if op == "!=":
        return x != y
    return False
