"""Shared runner for the newer trajectory analysis tools."""

import math
import sys

from .main import GmxError, err_write, out_write, wrap_line
from .structures import read_frames, file_extension, Frame
from .trajectory import read_trajectory
from .groups import parse_ndx, default_groups
from .library import require_library_file
from .masses import warn_guess_masses, guess_masses
from .selections import (
    SelectionEngine, SelectionEvalError, SelectionSyntaxError,
    parse_selection_collection,
)


def too_few_selections(multiple=False, expected=1):
    if multiple:
        return GmxError(
            "Too few selections provided\n", title="Error in user input:",
            source="src/gromacs/selection/selectionoption.cpp", line=107,
            function=("void gmx::SelectionOptionStorage::addSelections"
                      "(const SelectionList&, bool)"),
            module_stage=True)
    return GmxError(
        f"Too few selections provided; got 0, expected {expected}\n",
        title="Error in user input:",
        source="src/gromacs/selection/selectioncollection.cpp", line=404,
        function=("gmx::SelectionList gmx::{anonymous}::runParser"
                  "(yyscan_t, gmx::TextInputStream*, bool, int, const string&)"),
        module_stage=True)


def too_many_selections(got, expected=1):
    return GmxError(
        f"Too many selections provided; got {got}, expected {expected}\n",
        title="Error in user input:",
        source="src/gromacs/selection/selectioncollection.cpp", line=404,
        function=("gmx::SelectionList gmx::{anonymous}::runParser"
                  "(yyscan_t, gmx::TextInputStream*, bool, int, const string&)"),
        module_stage=True)


def invalid_group_references(refs):
    lines = ["Invalid index group reference(s)"]
    for r in refs:
        lines.append(f"  Cannot match '{r}', because no such index group "
