    def _sf_assigned_to(self, option_name):
        sf = self._sf_texts()
        if not sf:
            return None
        order = self.state.occurrence_order
        if "sf" not in order:
            return sf
        prior = [n for n in order[:order.index("sf")]
                 if self.state.specs.get(n, {}).get("kind") == "selection"]
        if option_name in prior:
            return sf
        if not prior:
            return sf
        return None

    def get_selections(self, option_name, *, required=True, multiple=False,
                       default_text=None, min_count=None, max_count=None):
        state = self.state
        texts = None
        is_set = state.is_set(option_name)
        raw = state.raw_values.get(option_name) or []
        sf_texts = self._sf_assigned_to(option_name)
        if is_set and raw:
            texts = list(raw)
        elif is_set and not raw:
            texts = sf_texts if sf_texts is not None else self._prompt_texts()
        elif not is_set:
            if sf_texts is not None and required:
                texts = sf_texts
            elif default_text is not None:
                texts = [default_text]
            elif required:
                texts = self._prompt_texts()
            else:
                texts = []
        compiled = []
        variables = {}
        for text in texts or []:
            try:
                compiled.extend(parse_selection_collection(text, variables))
            except SelectionSyntaxError as e:
                # Syntax errors are normally caught while parsing the
                # command line; interactive/file input reaches this path.
                raise GmxError(
                    f"Invalid selection '{text}'\n"
                    f"  Near '{e.token}'\n    syntax error\n",
                    title="Error in user input:",
                    source="src/gromacs/selection/selectioncollection.cpp",
                    line=404, function=None, module_stage=True)
        if min_count is None:
            min_count = 1 if required else 0
        if len(compiled) < min_count:
            raise too_few_selections(multiple=multiple, expected=min_count)
        if max_count is None and not multiple:
            max_count = 1 if required or compiled else None
        if max_count is not None and len(compiled) > max_count:
            raise too_many_selections(len(compiled), max_count)
