        # Share the variable definitions with the engine for evaluation.
        self.engine.variables.update(variables)
        return compiled

    def _prompt_texts(self):
        lines = []
        while True:
            line = sys.stdin.readline()
            if line == "":
                break
            if line.strip() == "":
                break
            lines.append(line.rstrip("\n") + " ")
