    def _validate_groups(self, compiled, variables):
        refs = []

        def visit(node):
            if not isinstance(node, tuple) or not node:
                return
            if node[0] == "group_name":
                name = node[1]
                try:
                    self.engine._find_group(name)
                except SelectionEvalError:
                    ref = f'group "{name}"'
                    if ref not in refs:
                        refs.append(ref)
                return
            if node[0] == "group_index":
                k = node[1]
                if not (0 <= k < len(self.groups)):
                    ref = f"group {k}"
                    if ref not in refs:
                        refs.append(ref)
                return
            if node[0] == "var":
                stored = variables.get(node[1]) or self.engine.variables.get(node[1])
                if stored is not None:
                    visit(stored[1] if stored and stored[0] == "numvar" else stored)
                return
            for child in node[1:]:
                if isinstance(child, tuple):
                    visit(child)

        for c in compiled:
            visit(c.node)
        if refs:
            raise invalid_group_references(refs)

