    def _fgroup_indices(self):
        if "fgroup" in self.state.specs and self.state.is_set("fgroup"):
            compiled = self.get_selections(
                "fgroup", required=True, multiple=False)
            if compiled:
                return self.engine.evaluate_atoms(compiled[0].node, self.topology)
        return None

    def iter_frames(self):
        traj = self.traj_file or self.struct_file
        raw_frames = read_trajectory(traj)
        fgroup = self._fgroup_indices()
        tu = self.state.value("tu") or "ps"
        factor = {"fs": 0.001, "ps": 1.0, "ns": 1000.0, "us": 1e6,
                  "ms": 1e9, "s": 1e12}.get(tu, 1.0)
        begin = (float(self.state.value("b")) * factor
                 if self.state.is_set("b") else None)
        end = (float(self.state.value("e")) * factor
               if self.state.is_set("e") else None)
        dt = (float(self.state.value("dt")) * factor
              if self.state.is_set("dt") else 0.0)
        first_time = raw_frames[0].time if raw_frames else 0.0
        count = 0
        last = first_time
        for raw in raw_frames:
            t = raw.time
            if begin is not None and t < begin - 1e-6:
                continue
            if end is not None and t > end + 1e-6:
                continue
            if dt:
                ref = begin if begin is not None else first_time
                ratio = (t - ref) / dt
                if abs(ratio - round(ratio)) > 1e-4:
                    continue
            frame = self.topology.copy()
            frame.box = raw.box
            frame.time = raw.time
            frame.step = raw.step
            frame.title = raw.title
            if fgroup is None:
                mapping = list(range(min(len(raw.atoms), len(frame.atoms))))
            else:
                mapping = fgroup
            for j, ti in enumerate(mapping):
                if j < len(raw.atoms) and ti < len(frame.atoms):
                    frame.atoms[ti].pos = raw.atoms[j].pos
                    frame.atoms[ti].vel = raw.atoms[j].vel
            count += 1
            last = t
            yield frame, raw
        self._analyzed = count
        self._last_time = last

    def finish(self):
        err_write(f"Analyzed {self._analyzed} frames, last time "
                  f"{self._last_time:.3f}\n")
