# ---------------------------------------------------------------------------
# gmx traj
# ---------------------------------------------------------------------------

def tool_traj(ctx, state):
    runner = LegacyRunner(ctx, state, mass_db=True)
    ng = int(state.value("ng") or 1)
    groups = []
    for _ in range(ng):
        groups.append(prompt_group_stderr(ctx, runner.groups))
    com_mode = bool(state.value("com")) or bool(state.value("mol")) \
        or state.is_set("ot") or state.is_set("ekt") or state.is_set("ekr")
    any_set = any(state.is_set(o) for o in ("x", "y", "z", "len"))
    comps = []
    if not any_set:
        comps = ["x", "y", "z"]
    else:
        if state.value("len"):
            comps.append("len")
        for c in ("x", "y", "z"):
            if state.is_set(c) and state.value(c):
                comps.append(c)
    ox_rows = []; ov_rows = []; of_rows = []; ob_rows = []
    ot_rows = []; ekt_rows = []; ekr_rows = []
    vel_sums = {}
    coord_sums = {}
    nframes = 0
    prev_coords = None
    nojump = bool(state.value("nojump"))
    mol_mode = bool(state.value("mol"))

    def group_positions(frame, grp):
        idx = list(grp.indices)
        if mol_mode:
            # Index numbers are molecule numbers (1-based); with a text
            # topology there is a single molecule containing all atoms.
            idx = list(range(len(frame.atoms))) if idx and idx[0] == 0 else []
        if com_mode:
            if not idx:
                return []
            weights = [runner.masses[i] for i in idx]
            total = sum(weights)
            if total <= 0:
                weights = [1.0] * len(idx); total = float(len(idx))
            pos = tuple(sum(weights[k] * frame.atoms[idx[k]].pos[d]
                            for k in range(len(idx))) / total
                        for d in range(3))
            vel = tuple(sum(weights[k] * (frame.atoms[idx[k]].vel or (0, 0, 0))[d]
                            for k in range(len(idx))) / total
                        for d in range(3))
            return [(pos, vel, idx)]
        return [(frame.atoms[i].pos, frame.atoms[i].vel, [i]) for i in idx]

    for frame, _raw in runner.iter_frames():
        # -nojump: unwrap coordinates relative to the previous frame.
        if nojump and prev_coords is not None:
            box = frame.box
            for a in frame.atoms:
                p = list(a.pos)
                for d in range(3):
                    L = box[d][d] if box else 0.0
                    if L:
                        while p[d] - prev_coords[id(a)][d] > 0.5 * L:
                            p[d] -= L
                        while p[d] - prev_coords[id(a)][d] < -0.5 * L:
                            p[d] += L
                a.pos = tuple(p)
        prev_coords = {id(a): a.pos for a in frame.atoms}
        ox = [frame.time]; ov = [frame.time]; of = [frame.time]
        for grp in groups:
            for pos, vel, _idx in group_positions(frame, grp):
                for c in comps:
                    if c == "len":
                        ox.append(math.sqrt(sum(v * v for v in pos)))
                        if vel is not None:
                            ov.append(math.sqrt(sum(v * v for v in vel)))
                    else:
                        d = "xyz".index(c)
                        ox.append(pos[d])
                        if vel is not None:
                            ov.append(vel[d])
