            if total <= 0:
                weights = [1.0] * len(idx); total = float(len(idx))
            pos = tuple(sum(weights[k] * frame.atoms[idx[k]].pos[d]
                            for k in range(len(idx))) / total
                        for d in range(3))
            vel = tuple(sum(weights[k] * (frame.atoms[idx[k]].vel or (0, 0, 0))[d]
                            for k in range(len(idx))) / total
                        for d in range(3))
            return [(pos, vel, idx)]
        return [(frame.atoms[i].pos, frame.atoms[i].vel, [i]) for i in idx]

    for frame, _raw in runner.iter_frames():
        # -nojump: unwrap coordinates relative to the previous frame.
        if nojump and prev_coords is not None:
            box = frame.box
            for a in frame.atoms:
                p = list(a.pos)
                for d in range(3):
                    L = box[d][d] if box else 0.0
                    if L:
                        while p[d] - prev_coords[id(a)][d] > 0.5 * L:
                            p[d] -= L
                        while p[d] - prev_coords[id(a)][d] < -0.5 * L:
                            p[d] += L
                a.pos = tuple(p)
        prev_coords = {id(a): a.pos for a in frame.atoms}
        ox = [frame.time]; ov = [frame.time]; of = [frame.time]
        for grp in groups:
            for pos, vel, _idx in group_positions(frame, grp):
                for c in comps:
                    if c == "len":
                        ox.append(math.sqrt(sum(v * v for v in pos)))
                        if vel is not None:
                            ov.append(math.sqrt(sum(v * v for v in vel)))
                    else:
                        d = "xyz".index(c)
                        ox.append(pos[d])
                        if vel is not None:
                            ov.append(vel[d])
                of.extend([0.0] * len(comps))
                for i in _idx:
                    vel_sums[i] = [vel_sums.get(i, [0.0, 0.0, 0.0])[d]
                                   + ((frame.atoms[i].vel or (0, 0, 0))[d])
                                   for d in range(3)]
                    cs = coord_sums.setdefault(i, [0.0, 0.0, 0.0])
                    for d in range(3):
                        cs[d] += frame.atoms[i].pos[d]
        if state.is_set("ox"):
            ox_rows.append(ox)
        if state.is_set("ov"):
            ov_rows.append(ov)
        if state.is_set("of"):
            of_rows.append(of)
        if state.is_set("ob"):
            b = frame.box
            ob_rows.append([frame.time,
                            math.sqrt(sum(x * x for x in b[0])),
                            math.sqrt(sum(x * x for x in b[1])),
                            math.sqrt(sum(x * x for x in b[2]))])
        if state.is_set("ot") or state.is_set("ekt") or state.is_set("ekr"):
            ot, ekt, ekr = _traj_energies(runner, frame, groups)
            if state.is_set("ot"):
                ot_rows.append([frame.time] + ot)
            if state.is_set("ekt"):
                ekt_rows.append([frame.time] + ekt)
            if state.is_set("ekr"):
                ekr_rows.append([frame.time] + ekr)
        nframes += 1

    def legends_for(suffix):
        out = []
        for gi, grp in enumerate(groups):
            positions = group_positions(runner.reference, grp)
            for pi, (_p, _v, idx) in enumerate(positions):
                if com_mode:
                    label = grp.name
                else:
                    label = f"atom {idx[0] + 1}" if idx else f"pos {pi + 1}"
                for c in comps:
                    if c == "len":
                        out.append(label)
                    else:
                        out.append(f"{label} {c.upper()}")
        return out

    fmt_tab = lambda r: "\t".join(fmt_g(f32(v)) for v in r)
    if state.is_set("ox"):
        write_xvg(ctx, state.file_value("ox"), ox_rows, title="Coordinate",
                  xlabel="Time (ps)", ylabel="Coordinate (nm)",
                  legends=legends_for("x"), xvg_format=state.value("xvg"),
                  row_formatter=fmt_tab)
    if state.is_set("ov"):
        write_xvg(ctx, state.file_value("ov"), ov_rows, title="Velocity",
                  xlabel="Time (ps)", ylabel="Velocity (nm/ps)",
                  legends=legends_for("v"), xvg_format=state.value("xvg"),
                  row_formatter=fmt_tab)
    if state.is_set("of"):
        write_xvg(ctx, state.file_value("of"), of_rows, title="Force",
                  xlabel="Time (ps)", ylabel="Force (kJ/mol nm)",
                  legends=legends_for("f"), xvg_format=state.value("xvg"),
                  row_formatter=fmt_tab)
    if state.is_set("ob"):
        write_xvg(ctx, state.file_value("ob"), ob_rows, title="Box size",
                  xlabel="Time (ps)", ylabel="Box (nm)",
                  legends=["X", "Y", "Z"], xvg_format=state.value("xvg"),
                  row_formatter=fmt_tab)
    if state.is_set("ot"):
        write_xvg(ctx, state.file_value("ot"), ot_rows, title="Temperature",
                  xlabel="Time (ps)", ylabel="T (K)",
                  legends=[g.name for g in groups],
                  xvg_format=state.value("xvg"), row_formatter=fmt_tab)
    if state.is_set("ekt"):
        write_xvg(ctx, state.file_value("ekt"), ekt_rows,
                  title="Translational kinetic energy", xlabel="Time (ps)",
                  ylabel="Ekin (kJ/mol)", legends=[g.name for g in groups],
                  xvg_format=state.value("xvg"), row_formatter=fmt_tab)
    if state.is_set("ekr"):
        write_xvg(ctx, state.file_value("ekr"), ekr_rows,
                  title="Rotational kinetic energy", xlabel="Time (ps)",
                  ylabel="Ekin (kJ/mol)", legends=[g.name for g in groups],
                  xvg_format=state.value("xvg"), row_formatter=fmt_tab)
    if state.is_set("oxt"):
        _traj_write_oxt(ctx, state, runner, groups)
    if state.is_set("vd"):
        _traj_velocity_distribution(ctx, state, runner)
    if state.is_set("cv") or state.is_set("cf"):
        _traj_average_pdb(ctx, state, runner, vel_sums, coord_sums, nframes)
    return ctx.finish_success(0)


def _traj_energies(runner, frame, groups):
    temps = []; ekts = []; ekrs = []
    boltz = 0.00831446261815324
    for grp in groups:
        idx = list(grp.indices)
        if not idx:
            temps.append(0.0); ekts.append(0.0); ekrs.append(0.0)
            continue
        masses = [runner.masses[i] for i in idx]
        total = sum(masses)
        if total <= 0:
            temps.append(0.0); ekts.append(0.0); ekrs.append(0.0)
            continue
        vels = [(frame.atoms[i].vel or (0.0, 0.0, 0.0)) for i in idx]
        vcom = [sum(masses[k] * vels[k][d] for k in range(len(idx))) / total
                for d in range(3)]
        ekt = 0.5 * total * sum(v * v for v in vcom)
        ke_rel = 0.5 * sum(masses[k] * sum(
            (vels[k][d] - vcom[d]) ** 2 for d in range(3))
            for k in range(len(idx)))
        dof = 3 * len(idx)
        temp = 2 * (ekt + ke_rel) / (dof * boltz) if dof else 0.0
        temps.append(temp); ekts.append(ekt); ekrs.append(ke_rel)
    return temps, ekts, ekrs


def _traj_write_oxt(ctx, state, runner, groups):
    # Re-read the trajectory and write the selected atoms (no progress
    # output the second time in this implementation).
    from .structures import read_frames, Frame, format_gro, format_pdb, format_g96

    outfile = state.file_value("oxt")
    ext = outfile.rsplit(".", 1)[-1].lower() if "." in outfile else ""
    if ext not in ("gro", "g96", "pdb", "brk", "ent"):
        raise GmxError(
            "Writing binary trajectories is not supported by this "
            "reimplementation.\n", title="Fatal error:",
            source="src/gromacs/fileio/trxio.cpp", line=1, function=None)
    frames = read_frames(runner.traj_file)
    keep = set()
    for g in groups:
        keep.update(g.indices)
    out = []
    for fr in frames:
        atoms = [fr.atoms[i] for i in sorted(keep) if i < len(fr.atoms)]
        out.append(Frame(fr.title, atoms, fr.box, fr.time, fr.step))
    if ext == "gro":
        text = "".join(format_gro(f) for f in out)
    elif ext == "g96":
        text = "".join(format_g96(f) for f in out)
    else:
        text = "".join(format_pdb(f) for f in out)
    ctx.write_output_file(outfile, text)


def _traj_velocity_distribution(ctx, state, runner):
    from .structures import read_frames

    binw = float(state.value("bin") or 1.0)
    speeds = []
    for fr in read_frames(runner.traj_file):
        for a in fr.atoms:
            if a.vel is not None:
                speeds.append(math.sqrt(sum(v * v for v in a.vel)))
    if not speeds:
        ctx.write_output_file(state.file_value("vd"), "")
        return
    maxv = max(speeds)
    nbins = max(1, int(math.ceil(maxv / binw))) if binw else 1
    counts = [0] * nbins
    ecounts = [0] * nbins
    masses = runner.masses
    # Kinetic energy distribution uses the same binning on energies.
    for fr in read_frames(runner.traj_file):
        for i, a in enumerate(fr.atoms):
            if a.vel is None:
                continue
            v = math.sqrt(sum(x * x for x in a.vel))
            idx = int(v / binw) if binw else 0
            if 0 <= idx < nbins:
                counts[idx] += 1
    rows = [[(i + 0.5) * binw, counts[i] / (len(speeds) * binw)
             if speeds and binw else 0.0] for i in range(nbins)]
    write_xvg(ctx, state.file_value("vd"), rows,
              title="Velocity distribution", xlabel="v (nm/ps)",
              ylabel="p(v)", legends=[], xvg_format=state.value("xvg"),
              row_formatter=lambda r: "\t".join(fmt_g(f32(v)) for v in r))


def _traj_average_pdb(ctx, state, runner, vel_sums, coord_sums, nframes):
    from .structures import format_pdb

    for opt, is_vel in (("cv", True), ("cf", False)):
        if not state.is_set(opt):
            continue
        frame = runner.reference.copy()
        maxnorm = 0.0
        norms = {}
        for i, a in enumerate(frame.atoms):
            if i in coord_sums and nframes:
                a.pos = tuple(coord_sums[i][d] / nframes for d in range(3))
            v = vel_sums.get(i, [0.0, 0.0, 0.0])
            avg = [x / nframes for x in v] if nframes else [0.0, 0.0, 0.0]
            norms[i] = math.sqrt(sum(x * x for x in avg)) if is_vel else 0.0
            maxnorm = max(maxnorm, norms[i])
        scale = float(state.value("scale") or 0.0)
        if scale == 0:
            scale = 10.0 / maxnorm if maxnorm else 1.0
        for i, a in enumerate(frame.atoms):
            a.bfactor = norms.get(i, 0.0) * scale
        ctx.write_output_file(state.file_value(opt), format_pdb(frame))
