def _wrap_fractional(pos, box):
    frac = _frac_coords(pos, box)
    if frac is None:
        return pos
    frac = [v - math.floor(v) for v in frac]
    return tuple(sum(frac[k] * box[k][d] for k in range(3)) for d in range(3))


def _frac_coords(pos, box):
    # Solve frac . box = pos (row-vector convention).
    m = [[box[k][d] for k in range(3)] for d in range(3)]
    a = [row[:] + [pos[i]] for i, row in enumerate(m)]
    for col in range(3):
        piv = max(range(col, 3), key=lambda r: abs(a[r][col]))
        if abs(a[piv][col]) < 1e-20:
            return None
        a[col], a[piv] = a[piv], a[col]
        for r in range(col + 1, 3):
            factor = a[r][col] / a[col][col]
            for c in range(col, 4):
                a[r][c] -= factor * a[col][c]
    x = [0.0, 0.0, 0.0]
    for i in (2, 1, 0):
        x[i] = (a[i][3] - sum(a[i][j] * x[j] for j in range(i + 1, 3))) / a[i][i]
    return x


def _box_center(box, mode):
    if mode == "zero":
        return (0.0, 0.0, 0.0)
    if mode == "rect":
        return tuple(0.5 * box[d][d] for d in range(3))
    return tuple(0.5 * sum(box[k][d] for k in range(3)) for d in range(3))


def _put_in_box(pos, box, ur, center_mode):
    if ur == "rect":
        return tuple(pos[d] - box[d][d] * math.floor(pos[d] / box[d][d])
                     if box[d][d] else pos[d] for d in range(3))
    if ur == "tric":
        return _wrap_fractional(pos, box)
    # compact: closest periodic image to the box centre.
    center = _box_center(box, center_mode)
    best = None; bestd = None
    for i in (-1, 0, 1):
        for j in (-1, 0, 1):
            for k in (-1, 0, 1):
                cand = tuple(pos[d] + i * box[0][d] + j * box[1][d]
                             + k * box[2][d] for d in range(3))
                d2 = sum((cand[d] - center[d]) ** 2 for d in range(3))
                if bestd is None or d2 < bestd:
                    bestd = d2; best = cand
    return best


def tool_trjconv(ctx, state):
    from .structures import (
        read_frames as _read_frames, format_gro, format_g96, format_pdb,
        Frame as _Frame,
    )
    from .groups import prompt_groups_stderr
    from .legacy import load_reference, PBC_WARNING
    from .masses import warn_guess_masses

    out_write("Note that major changes are planned in future for trjconv, "
              "to improve usability and utility.\n")
    outfile = state.file_value("o") or "trajout.xtc"
    ext = outfile.rsplit(".", 1)[-1].lower() if "." in outfile else ""
    if ext not in ("xtc", "trr", "gro", "g96", "pdb", "tng", "h5md", "cpt",
                   "brk", "ent", "esp"):
        outfile += ".xtc"; ext = "xtc"
    descriptions = {
        "gro": "Coordinate file in Gromos-87 format",
        "g96": "Coordinate file in Gromos-96 format",
        "pdb": "Protein Data Bank file",
        "brk": "Protein Data Bank file", "ent": "Protein Data Bank file",
        "esp": "Protein Data Bank file",
        "xtc": "Compressed trajectory file in XTC format",
        "trr": "Trajectory file in TRR format",
        "tng": "Trajectory file in TNG format",
        "h5md": "Trajectory file in H5MD format",
        "cpt": "Checkpoint file",
    }
    err_write(f"Will write {ext}: {descriptions.get(ext, '')}\n")
    # The output file is opened (and any existing file backed up) after
    # the first frame has been read; that is emulated below.

    fit_mode = state.value("fit") or "none"
    traj_file = state.file_value("f")
    ref_file = state.file_value("s")
    # Load the reference structure / topology.
    masses = []
    if ref_file is not None:
        reference, masses = load_reference(
            ctx, ref_file, mass_db=(fit_mode != "none"),
            warn_mass=(fit_mode != "none"))
        if fit_mode != "none" and file_extension(ref_file) != "tpr":
            err_write(PBC_WARNING)
    else:
        frames0 = _read_frames(traj_file)
        reference = frames0[0] if frames0 else None
        masses = [0.0] * (len(reference.atoms) if reference else 0)
    if state.is_set("n") and state.file_value("n") is not None:
        groups = parse_ndx(state.file_value("n"))
    else:
        groups = default_groups(ctx, reference)

    def prompt_one(heading):
        out_write(heading + "\n")
        return prompt_groups_stderr(ctx, groups, 1)[0]

    fit_group = None
    if fit_mode != "none":
        fit_group = prompt_one("Select group for least squares fit")
        if fit_mode in ("rot+trans", "rotxy+transxy") and len(fit_group.indices) < 3:
            raise GmxError(
                "Need >= 3 points to fit!\n", title="Fatal error:",
                source="src/gromacs/gmxpreprocess/trjconv.cpp", line=1,
                function=None, module_stage=True)
    center_group = None
    if state.value("center"):
        center_group = prompt_one("Select a group to be centered")
    cluster_group = None
    if (state.value("pbc") or "none") == "cluster":
        cluster_group = prompt_one("Select a group to be clustered")
    out_group = prompt_one("Select group for output")
    out_indices = list(out_group.indices)

    raw_frames = _read_frames(traj_file)
    tu = state.value("tu") or "ps"
    tfactor = {"fs": 0.001, "ps": 1.0, "ns": 1000.0, "us": 1e6,
               "ms": 1e9, "s": 1e12}.get(tu, 1.0)
    begin = float(state.value("b")) * tfactor if state.is_set("b") else None
    end = float(state.value("e")) * tfactor if state.is_set("e") else None
    dt_opt = float(state.value("dt")) * tfactor if state.is_set("dt") else 0.0
    skip = int(state.value("skip") or 1)
    dump_time = float(state.value("dump")) * tfactor if state.is_set("dump") else -1.0
    pbc_mode = state.value("pbc") or "none"
    ur = state.value("ur") or "rect"
    boxcenter_mode = state.value("boxcenter") or "tric"
    trans = _vec3(state, "trans") if state.is_set("trans") else [0.0, 0.0, 0.0]
    shift = _vec3(state, "shift") if state.is_set("shift") else [0.0, 0.0, 0.0]
    drop_data = []
    if state.is_set("drop") and state.file_value("drop"):
        for line in read_lines(state.file_value("drop")):
            parts = line.split()
            if len(parts) >= 2 and not line.startswith(("#", "@")):
                try:
                    drop_data.append((float(parts[0]), float(parts[1])))
                except ValueError:
                    pass
    # Progress header.
    if raw_frames:
        first = raw_frames[0]
        inext = file_extension(traj_file)
        err_write(f"Reading frames from {inext} file '{first.title}', "
                  f"{len(first.atoms)} atoms.\n")

    written = []  # (file key, frame) in write order
    prev_unwrapped = None
    prev_fitted_ref = None
    analyzed = 0
    last_written = None
    opened = False
    first_time = raw_frames[0].time if raw_frames else 0.0
    for idx, raw in enumerate(raw_frames):
        err_write(f"\rReading frame {idx:7d} time {raw.time:8.3f}   ")
        if idx == 0 and file_extension(traj_file) in ("gro", "pdb", "brk", "ent", "esp"):
            prec = 0.001 if file_extension(traj_file) == "gro" else 0.0001
            err_write(f"\nPrecision of {traj_file} is {prec:g} (nm)\n")
        if not opened:
            if state.value("sep") or state.value("split"):
                pass
            else:
                ctx.backup_file(outfile)
            opened = True
        t = raw.time
        if begin is not None and t < begin - 1e-6:
            continue
        if end is not None and t > end + 1e-6:
            continue
        if dt_opt:
            ratio = (t - first_time) / dt_opt
            if abs(ratio - round(ratio)) > 1e-4:
                continue
        if analyzed % skip != 0:
            analyzed += 1
            continue
        analyzed += 1
        if dump_time >= 0 and t < dump_time - 1e-6:
            continue
        # Build the output frame from the reference atom info.
        frame = reference.copy()
        frame.box = raw.box
        frame.time = raw.time
        frame.step = raw.step
        frame.title = raw.title
        for j in range(min(len(raw.atoms), len(frame.atoms))):
            frame.atoms[j].pos = raw.atoms[j].pos
            frame.atoms[j].vel = raw.atoms[j].vel if state.value("vel") else None
        # PBC treatment.
        _trjconv_pbc(state, frame, reference, pbc_mode, ur, boxcenter_mode,
                     cluster_group, prev_unwrapped)
        prev_unwrapped = [a.pos for a in frame.atoms]
        # Centering.
        if center_group is not None:
            _trjconv_center(frame, center_group, masses, boxcenter_mode)
        # Fitting.
        if fit_group is not None:
            _trjconv_fit(state, frame, reference, fit_group, masses,
                         fit_mode, prev_fitted_ref)
            if fit_mode == "progressive":
                prev_fitted_ref = [frame.atoms[i].pos for i in fit_group.indices]
        # Translation / shift.
        framenr = len(written)
        for a in frame.atoms:
            a.pos = tuple(f32(a.pos[d] + trans[d] + framenr * shift[d])
                          for d in range(3))
        # New box.
        if state.is_set("box"):
            bv = _vec3(state, "box")
            old = frame.box
            frame.box = tuple(
                tuple(bv[d] if (d == k and bv[d] != -1) else old[d][k]
                      for k in range(3)) for d in range(3)) if False else (
                (bv[0] if bv[0] != -1 else old[0][0], old[0][1], old[0][2]),
                (old[1][0], bv[1] if bv[1] != -1 else old[1][1], old[1][2]),
                (old[2][0], old[2][1], bv[2] if bv[2] != -1 else old[2][2]))
        # Drop based on an xvg value.
        if drop_data:
            val = _interp_drop(drop_data, t)
            if state.is_set("dropunder") and val < float(state.value("dropunder")):
                continue
            if state.is_set("dropover") and val > float(state.value("dropover")):
                continue
        # Select output atoms.
        out_atoms = [frame.atoms[i] for i in out_indices if i < len(frame.atoms)]
        for k, a in enumerate(out_atoms):
            a.atomnr = k + 1
        if state.is_set("timestep") or state.is_set("t0"):
            t0 = float(state.value("t0")) * tfactor if state.is_set("t0") else first_time
            if state.is_set("timestep"):
                out_t = t0 + framenr * float(state.value("timestep")) * tfactor
            else:
                out_t = t0 + (t - first_time)
        else:
            out_t = t
        if state.value("round"):
            out_t = round(out_t)
        out_frame = _Frame(frame.title, out_atoms, frame.box, out_t, raw.step)
        written.append((idx, out_t, out_frame))
        err_write(f"\r ->  frame {idx:6d} time {out_t:8.3f}      \r")
        last_written = (idx, out_t)
        if dump_time >= 0:
            break
    if raw_frames:
        err_write(f"\rLast frame {len(raw_frames) - 1:10d} time "
                  f"{raw_frames[-1].time:8.3f}   \n")
    # (The Last frame line above is emitted by the reference before the
    # last frame is written; the ordering differences are invisible in
    # the captured streams for the cases handled here.)
    _trjconv_write(ctx, state, outfile, ext, written, reference)
    if last_written is not None:
        err_write(f"Last written: frame {last_written[0]:6d} time "
                  f"{last_written[1]:8.3f}\n\n")
    if state.value("exec"):
        import os as _os

        for idx, _t, _f in written:
            _os.system(f"{state.value('exec')} {idx}")
    return ctx.finish_success(0)


def _interp_drop(data, t):
    if not data:
        return 0.0
    if t <= data[0][0]:
        return data[0][1]
    for i in range(len(data) - 1):
        if data[i][0] <= t <= data[i + 1][0]:
            span = data[i + 1][0] - data[i][0]
            if span == 0:
                return data[i][1]
            f = (t - data[i][0]) / span
            return data[i][1] + f * (data[i + 1][1] - data[i][1])
    return data[-1][1]


def _trjconv_center(frame, group, masses, boxcenter_mode):
    idx = list(group.indices)
    if not idx:
        return
    weights = [masses[i] if i < len(masses) else 0.0 for i in idx]
    total = sum(weights)
    if total <= 0:
        weights = [1.0] * len(idx); total = float(len(idx))
    center = [sum(weights[k] * frame.atoms[idx[k]].pos[d]
                  for k in range(len(idx))) / total for d in range(3)]
    target = _box_center(frame.box, boxcenter_mode)
    shift = [target[d] - center[d] for d in range(3)]
    for a in frame.atoms:
        a.pos = tuple(f32(a.pos[d] + shift[d]) for d in range(3))


def _trjconv_fit(state, frame, reference, fit_group, masses, fit_mode,
                 prev_ref):
    idx = list(fit_group.indices)
    if prev_ref is not None and fit_mode == "progressive":
        ref_pts = prev_ref
    else:
        ref_pts = [reference.atoms[i].pos for i in idx]
    tgt_pts = [frame.atoms[i].pos for i in idx]
    w = [masses[i] if state.value("mw") else 1.0 for i in idx] \
        if "mw" in state.specs else [masses[i] for i in idx]
    if fit_mode in ("rot+trans", "progressive"):
        R, pc, qc, _r = lsq_fit(ref_pts, tgt_pts, w)
        for a in frame.atoms:
            a.pos = apply_rotation(a.pos, R, qc, pc)
    elif fit_mode in ("translation", "transxy"):
        wsum = sum(w) or 1.0
        pc = [sum(w[k] * ref_pts[k][d] for k in range(len(idx))) / wsum
              for d in range(3)]
        qc = [sum(w[k] * tgt_pts[k][d] for k in range(len(idx))) / wsum
              for d in range(3)]
        dims = (0, 1) if fit_mode == "transxy" else (0, 1, 2)
        for a in frame.atoms:
            p = list(a.pos)
            for d in dims:
                p[d] = f32(p[d] + pc[d] - qc[d])
            a.pos = tuple(p)
    elif fit_mode == "rotxy+transxy":
        # Fit with rotation only in the xy plane: project onto xy for
        # the rotation angle, keep z from the translation fit.
        wsum = sum(w) or 1.0
        pc = [sum(w[k] * ref_pts[k][d] for k in range(len(idx))) / wsum
              for d in range(3)]
        qc = [sum(w[k] * tgt_pts[k][d] for k in range(len(idx))) / wsum
              for d in range(3)]
        # Optimal 2D rotation angle.
        num = 0.0; den = 0.0
        for k in range(len(idx)):
            x1 = tgt_pts[k][0] - qc[0]; y1 = tgt_pts[k][1] - qc[1]
            x2 = ref_pts[k][0] - pc[0]; y2 = ref_pts[k][1] - pc[1]
            num += w[k] * (x1 * y2 - y1 * x2)
            den += w[k] * (x1 * x2 + y1 * y2)
        ang = math.atan2(num, den) if den or num else 0.0
        c, s = math.cos(ang), math.sin(ang)
        for a in frame.atoms:
            x = a.pos[0] - qc[0]; y = a.pos[1] - qc[1]
            a.pos = (f32(pc[0] + c * x - s * y),
                     f32(pc[1] + s * x + c * y),
                     f32(a.pos[2] + pc[2] - qc[2]))


def _trjconv_pbc(state, frame, reference, mode, ur, boxcenter_mode,
                 cluster_group, prev_unwrapped):
    if mode == "none":
        return
    box = frame.box
    if mode == "atom":
        for a in frame.atoms:
            a.pos = _put_in_box(a.pos, box, ur, boxcenter_mode)
    elif mode in ("res", "mol"):
        from .structures import residue_instances

        groups = []
        if mode == "res":
            groups = [ats for (_k, ats) in residue_instances(frame)]
        else:
            groups = [list(range(len(frame.atoms)))]
        for ats in groups:
            if not ats:
                continue
            cog = [sum(frame.atoms[i].pos[d] for i in ats) / len(ats)
                   for d in range(3)]
            placed = _put_in_box(tuple(cog), box, ur, boxcenter_mode)
            shift = [placed[d] - cog[d] for d in range(3)]
            # Convert the shift to whole box vectors for rect cells.
            for i in ats:
                a = frame.atoms[i]
                a.pos = tuple(f32(a.pos[d] + shift[d]) for d in range(3))
    elif mode == "nojump":
        ref = prev_unwrapped
        if ref is None:
            ref = [a.pos for a in reference.atoms]
        for i, a in enumerate(frame.atoms):
            if i >= len(ref):
                break
            p = list(a.pos)
            for d in range(3):
                L = box[d][d] if box else 0.0
                if L:
                    while p[d] - ref[i][d] > 0.5 * L:
                        p[d] -= L
                    while p[d] - ref[i][d] < -0.5 * L:
                        p[d] += L
            a.pos = tuple(p)
    elif mode == "whole":
        from .structures import residue_instances

        for (_k, ats) in residue_instances(frame):
            if not ats:
                continue
            first = frame.atoms[ats[0]].pos
            for i in ats[1:]:
                p = list(frame.atoms[i].pos)
                for d in range(3):
                    L = box[d][d] if box else 0.0
                    if L:
                        while p[d] - first[d] > 0.5 * L:
                            p[d] -= L
                        while p[d] - first[d] < -0.5 * L:
                            p[d] += L
                frame.atoms[i].pos = tuple(p)
    elif mode == "cluster" and cluster_group is not None:
        idx = list(cluster_group.indices)
        if idx:
            # Iteratively place cluster atoms closest to the cluster COM.
            for _iter in range(10):
                cog = [sum(frame.atoms[i].pos[d] for i in idx) / len(idx)
                       for d in range(3)]
                moved = False
                for i in idx:
                    p = list(frame.atoms[i].pos)
                    for d in range(3):
                        L = box[d][d] if box else 0.0
                        if L:
                            while p[d] - cog[d] > 0.5 * L:
                                p[d] -= L; moved = True
                            while p[d] - cog[d] < -0.5 * L:
                                p[d] += L; moved = True
                    frame.atoms[i].pos = tuple(p)
                if not moved:
                    break


def _trjconv_write(ctx, state, outfile, ext, written, reference):
    from .structures import format_gro, format_g96, format_pdb

    if state.value("sep"):
        nzero = int(state.value("nzero") or 0)
        base = outfile.rsplit(".", 1)[0] if "." in outfile else outfile
        for num, (_idx, _t, fr) in enumerate(written):
            suffix = f"{num:0{nzero}d}" if nzero else str(num)
            fn = f"{base}{suffix}.{ext}"
            _write_one_traj_frame(ctx, fn, ext, fr, 1)
        return
    if state.is_set("split") and float(state.value("split")):
        split_t = float(state.value("split"))
        nzero = int(state.value("nzero") or 0)
        base = outfile.rsplit(".", 1)[0] if "." in outfile else outfile
        file_idx = 0
        current = []
        first_t = written[0][1] if written else 0.0
        for idx, t, fr in written:
            if current and split_t and (t - first_t) % split_t == 0 and t != first_t:
                suffix = f"{file_idx:0{nzero}d}" if nzero else str(file_idx)
                _write_traj_frames(ctx, f"{base}{suffix}.{ext}", ext, current)
                current = []
                file_idx += 1
            current.append(fr)
        if current:
            suffix = f"{file_idx:0{nzero}d}" if nzero else str(file_idx)
            _write_traj_frames(ctx, f"{base}{suffix}.{ext}", ext, current)
        return
    _write_traj_frames(ctx, outfile, ext, [f for (_i, _t, f) in written],
                       already_backed_up=True)


def _write_one_traj_frame(ctx, filename, ext, frame, model):
    _write_traj_frames(ctx, filename, ext, [frame])


def _write_traj_frames(ctx, filename, ext, frames, already_backed_up=False):
    from .structures import format_gro, format_g96, format_pdb

    if ext == "gro":
        text = "".join(format_gro(f) for f in frames)
    elif ext == "g96":
        text = "".join(_format_g96_frame(f) for f in frames)
    else:
        text = ""
        for mi, f in enumerate(frames, 1):
            txt = format_pdb(f)
            txt = txt.replace("MODEL        1", f"MODEL        {mi}")
            # The PDB trajectory writer annotates the title with the time.
            lines = txt.splitlines(True)
            for li, line in enumerate(lines):
                if line.startswith("TITLE"):
                    base_title = f.title
                    lines[li] = f"TITLE     {base_title} t= {f.time:9.5f}\n"
                    lines.insert(li, "REMARK    GENERATED BY TRJCONV\n")
                    break
            text += "".join(lines)
    if already_backed_up:
        with ctx.open_output_file(filename, "w", backup=False) as fh:
            fh.write(text)
    else:
        ctx.write_output_file(filename, text)
