def _wrap_fractional(pos, box):
    frac = _frac_coords(pos, box)
    if frac is None:
        return pos
    frac = [v - math.floor(v) for v in frac]
    return tuple(sum(frac[k] * box[k][d] for k in range(3)) for d in range(3))


def _frac_coords(pos, box):
    # Solve frac . box = pos (row-vector convention).
    m = [[box[k][d] for k in range(3)] for d in range(3)]
    a = [row[:] + [pos[i]] for i, row in enumerate(m)]
    for col in range(3):
        piv = max(range(col, 3), key=lambda r: abs(a[r][col]))
        if abs(a[piv][col]) < 1e-20:
            return None
        a[col], a[piv] = a[piv], a[col]
        for r in range(col + 1, 3):
            factor = a[r][col] / a[col][col]
            for c in range(col, 4):
                a[r][c] -= factor * a[col][c]
    x = [0.0, 0.0, 0.0]
    for i in (2, 1, 0):
        x[i] = (a[i][3] - sum(a[i][j] * x[j] for j in range(i + 1, 3))) / a[i][i]
    return x


def _box_center(box, mode):
    if mode == "zero":
        return (0.0, 0.0, 0.0)
    if mode == "rect":
        return tuple(0.5 * box[d][d] for d in range(3))
    return tuple(0.5 * sum(box[k][d] for k in range(3)) for d in range(3))


def _put_in_box(pos, box, ur, center_mode):
    if ur == "rect":
        return tuple(pos[d] - box[d][d] * math.floor(pos[d] / box[d][d])
                     if box[d][d] else pos[d] for d in range(3))
    if ur == "tric":
        return _wrap_fractional(pos, box)
    # compact: closest periodic image to the box centre.
    center = _box_center(box, center_mode)
    best = None; bestd = None
    for i in (-1, 0, 1):
        for j in (-1, 0, 1):
            for k in (-1, 0, 1):
                cand = tuple(pos[d] + i * box[0][d] + j * box[1][d]
                             + k * box[2][d] for d in range(3))
                d2 = sum((cand[d] - center[d]) ** 2 for d in range(3))
                if bestd is None or d2 < bestd:
                    bestd = d2; best = cand
    return best


