                return data[i][1]
            f = (t - data[i][0]) / span
            return data[i][1] + f * (data[i + 1][1] - data[i][1])
    return data[-1][1]


def _trjconv_center(frame, group, masses, boxcenter_mode):
    idx = list(group.indices)
    if not idx:
        return
    weights = [masses[i] if i < len(masses) else 0.0 for i in idx]
    total = sum(weights)
    if total <= 0:
        weights = [1.0] * len(idx); total = float(len(idx))
    center = [sum(weights[k] * frame.atoms[idx[k]].pos[d]
                  for k in range(len(idx))) / total for d in range(3)]
    target = _box_center(frame.box, boxcenter_mode)
    shift = [target[d] - center[d] for d in range(3)]
    for a in frame.atoms:
        a.pos = tuple(f32(a.pos[d] + shift[d]) for d in range(3))


def _trjconv_fit(state, frame, reference, fit_group, masses, fit_mode,
                 prev_ref):
    idx = list(fit_group.indices)
    if prev_ref is not None and fit_mode == "progressive":
        ref_pts = prev_ref
    else:
        ref_pts = [reference.atoms[i].pos for i in idx]
    tgt_pts = [frame.atoms[i].pos for i in idx]
    w = [masses[i] if state.value("mw") else 1.0 for i in idx] \
        if "mw" in state.specs else [masses[i] for i in idx]
    if fit_mode in ("rot+trans", "progressive"):
        R, pc, qc, _r = lsq_fit(ref_pts, tgt_pts, w)
        for a in frame.atoms:
            a.pos = apply_rotation(a.pos, R, qc, pc)
    elif fit_mode in ("translation", "transxy"):
        wsum = sum(w) or 1.0
        pc = [sum(w[k] * ref_pts[k][d] for k in range(len(idx))) / wsum
              for d in range(3)]
        qc = [sum(w[k] * tgt_pts[k][d] for k in range(len(idx))) / wsum
              for d in range(3)]
        dims = (0, 1) if fit_mode == "transxy" else (0, 1, 2)
        for a in frame.atoms:
            p = list(a.pos)
            for d in dims:
                p[d] = f32(p[d] + pc[d] - qc[d])
            a.pos = tuple(p)
    elif fit_mode == "rotxy+transxy":
        # Fit with rotation only in the xy plane: project onto xy for
        # the rotation angle, keep z from the translation fit.
        wsum = sum(w) or 1.0
        pc = [sum(w[k] * ref_pts[k][d] for k in range(len(idx))) / wsum
              for d in range(3)]
        qc = [sum(w[k] * tgt_pts[k][d] for k in range(len(idx))) / wsum
              for d in range(3)]
        # Optimal 2D rotation angle.
        num = 0.0; den = 0.0
        for k in range(len(idx)):
            x1 = tgt_pts[k][0] - qc[0]; y1 = tgt_pts[k][1] - qc[1]
            x2 = ref_pts[k][0] - pc[0]; y2 = ref_pts[k][1] - pc[1]
            num += w[k] * (x1 * y2 - y1 * x2)
            den += w[k] * (x1 * x2 + y1 * y2)
        ang = math.atan2(num, den) if den or num else 0.0
        c, s = math.cos(ang), math.sin(ang)
        for a in frame.atoms:
            x = a.pos[0] - qc[0]; y = a.pos[1] - qc[1]
            a.pos = (f32(pc[0] + c * x - s * y),
                     f32(pc[1] + s * x + c * y),
                     f32(a.pos[2] + pc[2] - qc[2]))


def _trjconv_pbc(state, frame, reference, mode, ur, boxcenter_mode,
                 cluster_group, prev_unwrapped):
    if mode == "none":
        return
    box = frame.box
    if mode == "atom":
        for a in frame.atoms:
            a.pos = _put_in_box(a.pos, box, ur, boxcenter_mode)
    elif mode in ("res", "mol"):
        from .structures import residue_instances

        groups = []
        if mode == "res":
            groups = [ats for (_k, ats) in residue_instances(frame)]
        else:
            groups = [list(range(len(frame.atoms)))]
        for ats in groups:
            if not ats:
                continue
            cog = [sum(frame.atoms[i].pos[d] for i in ats) / len(ats)
                   for d in range(3)]
            placed = _put_in_box(tuple(cog), box, ur, boxcenter_mode)
            shift = [placed[d] - cog[d] for d in range(3)]
            # Convert the shift to whole box vectors for rect cells.
            for i in ats:
                a = frame.atoms[i]
                a.pos = tuple(f32(a.pos[d] + shift[d]) for d in range(3))
    elif mode == "nojump":
        ref = prev_unwrapped
        if ref is None:
            ref = [a.pos for a in reference.atoms]
        for i, a in enumerate(frame.atoms):
            if i >= len(ref):
                break
            p = list(a.pos)
            for d in range(3):
                L = box[d][d] if box else 0.0
                if L:
                    while p[d] - ref[i][d] > 0.5 * L:
                        p[d] -= L
                    while p[d] - ref[i][d] < -0.5 * L:
                        p[d] += L
            a.pos = tuple(p)
    elif mode == "whole":
        from .structures import residue_instances

        for (_k, ats) in residue_instances(frame):
            if not ats:
                continue
            first = frame.atoms[ats[0]].pos
            for i in ats[1:]:
                p = list(frame.atoms[i].pos)
                for d in range(3):
                    L = box[d][d] if box else 0.0
                    if L:
                        while p[d] - first[d] > 0.5 * L:
                            p[d] -= L
                        while p[d] - first[d] < -0.5 * L:
                            p[d] += L
                frame.atoms[i].pos = tuple(p)
    elif mode == "cluster" and cluster_group is not None:
        idx = list(cluster_group.indices)
        if idx:
            # Iteratively place cluster atoms closest to the cluster COM.
            for _iter in range(10):
                cog = [sum(frame.atoms[i].pos[d] for i in idx) / len(idx)
                       for d in range(3)]
                moved = False
                for i in idx:
                    p = list(frame.atoms[i].pos)
                    for d in range(3):
                        L = box[d][d] if box else 0.0
                        if L:
                            while p[d] - cog[d] > 0.5 * L:
                                p[d] -= L; moved = True
                            while p[d] - cog[d] < -0.5 * L:
                                p[d] += L; moved = True
                    frame.atoms[i].pos = tuple(p)
                if not moved:
                    break


def _trjconv_write(ctx, state, outfile, ext, written, reference):
    from .structures import format_gro, format_g96, format_pdb

    if state.value("sep"):
        nzero = int(state.value("nzero") or 0)
        base = outfile.rsplit(".", 1)[0] if "." in outfile else outfile
        for num, (_idx, _t, fr) in enumerate(written):
            suffix = f"{num:0{nzero}d}" if nzero else str(num)
            fn = f"{base}{suffix}.{ext}"
            _write_one_traj_frame(ctx, fn, ext, fr, 1)
        return
    if state.is_set("split") and float(state.value("split")):
        split_t = float(state.value("split"))
        nzero = int(state.value("nzero") or 0)
        base = outfile.rsplit(".", 1)[0] if "." in outfile else outfile
        file_idx = 0
        current = []
        first_t = written[0][1] if written else 0.0
        for idx, t, fr in written:
            if current and split_t and (t - first_t) % split_t == 0 and t != first_t:
                suffix = f"{file_idx:0{nzero}d}" if nzero else str(file_idx)
                _write_traj_frames(ctx, f"{base}{suffix}.{ext}", ext, current)
                current = []
                file_idx += 1
            current.append(fr)
        if current:
            suffix = f"{file_idx:0{nzero}d}" if nzero else str(file_idx)
            _write_traj_frames(ctx, f"{base}{suffix}.{ext}", ext, current)
        return
    _write_traj_frames(ctx, outfile, ext, [f for (_i, _t, f) in written],
                       already_backed_up=True)


def _write_one_traj_frame(ctx, filename, ext, frame, model):
    _write_traj_frames(ctx, filename, ext, [frame])


def _write_traj_frames(ctx, filename, ext, frames, already_backed_up=False):
    from .structures import format_gro, format_g96, format_pdb

    if ext == "gro":
        text = "".join(format_gro(f) for f in frames)
    elif ext == "g96":
        text = "".join(_format_g96_frame(f) for f in frames)
    else:
        text = ""
        for mi, f in enumerate(frames, 1):
            txt = format_pdb(f)
            txt = txt.replace("MODEL        1", f"MODEL        {mi}")
            # The PDB trajectory writer annotates the title with the time.
            lines = txt.splitlines(True)
            for li, line in enumerate(lines):
                if line.startswith("TITLE"):
                    base_title = f.title
                    lines[li] = f"TITLE     {base_title} t= {f.time:9.5f}\n"
                    lines.insert(li, "REMARK    GENERATED BY TRJCONV\n")
                    break
            text += "".join(lines)
    if already_backed_up:
        with ctx.open_output_file(filename, "w", backup=False) as fh:
            fh.write(text)
    else:
        ctx.write_output_file(filename, text)
